def test_an_open_alert_episode_is_not_rebroadcast_and_reminds_once_after_a_day(env, monkeypatch):
    p = make(env)
    from ttp.daemon import Daemon
    start = time.time()
    clock = {"t": start}
    monkeypatch.setattr(time, "time", lambda: clock["t"])
    d = Daemon(p.base)
    sent = lambda: p.db.q("SELECT text FROM messages WHERE kind='alert' AND ref='auth:fake'")
    for hours in (0, 4.5, 9, 23):   # the old 4-hourly repeat
        clock["t"] = start + hours * 3600
        d.alert("auth:fake", f"fake is logged out ({hours} h)", "high", every_s=4 * 3600)
    assert [m["text"] for m in sent()] == ["fake is logged out (0 h)"]
    assert _episodes(p, "auth:fake")[0]["last"] == start + 23 * 3600, "a repeat updates the episode"
    for hours in (25, 30, 49, 73):
        clock["t"] = start + hours * 3600
        Daemon(p.base).alert("auth:fake", f"fake is logged out ({hours} h)", "high")
    assert [m["text"] for m in sent()] == ["fake is logged out (0 h)", "fake is logged out (25 h)"], \
        "one reminder after a day, then quiet"
    assert len(_episodes(p, "auth:fake")) == 1


def test_a_machine_wide_alert_is_broadcast_by_one_project_and_shown_quietly_by_the_others(env, monkeypatch):
    p = make(env)
    from ttp import alerts, notifier
    monkeypatch.setattr(alerts, "owner_alive", lambda owner: True)   # no daemon runs in the test
    from ttp.cli import bootstrap
    from ttp.daemon import Daemon
    from ttp.web import attention
    repo2 = env["tmp"] / "repo2"
    subprocess.run(["git", "clone", "-q", str(env["repo"]), str(repo2)], check=True)
    q = bootstrap(repo2, "second", "Another project.", "fake")
    for x in (p, q):
        x.db.x("INSERT INTO chats(id,created,label,last_active,last_read) VALUES('c1',?,?,?,0)",
               (time.time(), "t", time.time()))
    Daemon(p.base).alert("auth:fake", "fake is logged out", "high")
    Daemon(q.base).alert("auth:fake", "fake is logged out", "high")
    assert [m["text"] for m in p.db.unread_for_chat("c1", 0)] == ["fake is logged out"]
    assert q.db.unread_for_chat("c1", 0) == [], "the second project told the chat again"
    assert [a["cleared"] for a in notifier.alerts_since(q, 0)] == [True], "the desktop would show it twice"
    assert [m["text"] for m in attention(q.db, time.time())] == ["fake is logged out"], "web and status show it"
    # A condition only one project has (its own schedule) is not machine-wide.
    Daemon(q.base).alert("coordinator", "The coordinator failed", "high")
    q.db.set_kv("coordinator_failures", 1)
    assert [m["text"] for m in q.db.unread_for_chat("c1", 0)] == ["The coordinator failed"]
    # Once the claimer's episode clears, the claim is released: the other project may broadcast.
    p.db.x("INSERT INTO runs(role,provider,started,ended,status) VALUES('worker','fake',?,?,'ok')",
           (time.time() + 1, time.time() + 1))
    Daemon(p.base).sweep_alerts()
    q.db.x("INSERT INTO runs(role,provider,started,ended,status) VALUES('worker','fake',?,?,'ok')",
           (time.time() + 1, time.time() + 1))
    Daemon(q.base).sweep_alerts()
    assert [m["text"] for m in q.db.unread_for_chat("c1", 0)] == ["The coordinator failed"], \
        "a quiet episode clears quietly"
    Daemon(q.base).alert("auth:fake", "fake is logged out again", "high")
    Daemon(p.base).alert("auth:fake", "fake is logged out again", "high")
    assert [m["text"] for m in q.db.unread_for_chat("c1", 0)][-1] == "fake is logged out again"
    assert [m["text"] for m in p.db.unread_for_chat("c1", 0)][-1] == "Cleared: fake is logged in again; its queued work starts."


def _two_projects(env):
    from ttp.cli import bootstrap
    p = make(env)
    repo2 = env["tmp"] / "repo2"
    subprocess.run(["git", "clone", "-q", str(env["repo"]), str(repo2)], check=True)
    q = bootstrap(repo2, "second", "Another project.", "fake")
    for x in (p, q):
        x.db.x("INSERT INTO chats(id,created,label,last_active,last_read) VALUES('c1',?,?,?,0)",
               (time.time(), "t", time.time()))
    return p, q


def test_a_claim_from_an_earlier_logout_does_not_silence_the_next_one(env, monkeypatch):
    # p broadcast the first logout and stays idle (its episode and claim stay open); q posted it
    # quietly. The user logs in again and only q runs, so only q's episode clears.
    from ttp import alerts
    from ttp.daemon import Daemon
    monkeypatch.setattr(alerts, "owner_alive", lambda owner: True)
    p, q = _two_projects(env)
    Daemon(p.base).alert("auth:fake", "fake is logged out", "high")
    Daemon(q.base).alert("auth:fake", "fake is logged out", "high")
    assert q.db.unread_for_chat("c1", 0) == []
    stale = json.loads(alerts.claims_path().read_text())
    q.db.x("INSERT INTO runs(role,provider,started,ended,status) VALUES('worker','fake',?,?,'ok')",
           (time.time() + 1, time.time() + 1))
    Daemon(q.base).sweep_alerts()
    assert _episodes(p, "auth:fake")[0]["cleared"] is None and _episodes(q, "auth:fake")[0]["cleared"]
    assert json.loads(alerts.claims_path().read_text()) == {}, "the clear drops the idle project's claim"
    Daemon(q.base).alert("auth:fake", "fake is logged out again", "high")
    assert [m["text"] for m in q.db.unread_for_chat("c1", 0)] == ["fake is logged out again"], \
        "a new logout reached no chat"
    # Even a claim the clear could not drop (an older runtime, a failed write) is stale for a
    # project whose own episode cleared after it was taken.
    q.db.x("INSERT INTO runs(role,provider,started,ended,status) VALUES('worker','fake',?,?,'ok')",
           (time.time() + 2, time.time() + 2))
    Daemon(q.base).sweep_alerts()
    alerts.claims_path().write_text(json.dumps(stale))
    Daemon(q.base).alert("auth:fake", "fake is logged out a third time", "high")
    assert [m["text"] for m in q.db.unread_for_chat("c1", 0)][-1] == "fake is logged out a third time"


def test_a_stopped_claimers_claim_does_not_silence_the_others(env, monkeypatch):
    from ttp import alerts
    from ttp.daemon import Daemon
    p, q = _two_projects(env)
    running = {str(p.base), str(q.base)}
    monkeypatch.setattr(alerts, "owner_alive", lambda owner: owner in running)
    start = time.time()
    clock = {"t": start}
    monkeypatch.setattr(time, "time", lambda: clock["t"])
    Daemon(p.base).alert("auth:fake", "fake is logged out", "high")
    Daemon(q.base).alert("auth:fake", "fake is logged out", "high")
    assert q.db.unread_for_chat("c1", 0) == []
    running.discard(str(p.base))   # p's daemon stops for good, still holding the claim
    clock["t"] = start + alerts.REMIND_S + 1800   # before the claim's TTL runs out
    assert clock["t"] - start < alerts.CLAIM_TTL
    Daemon(q.base).alert("auth:fake", "fake is still logged out", "high")
    assert [m["text"] for m in q.db.unread_for_chat("c1", 0)] == ["fake is still logged out"], \
        "the day's reminder was left to a stopped project"
    from ttp.project import hostname
    assert json.loads(alerts.claims_path().read_text())[f"{hostname()}|auth:fake"]["owner"] == str(q.base)


def test_productive_burst_is_not_a_runaway_but_waste_is(env):
    p = make(env)
    from ttp import budget as bud
    now = time.time()
    wins = [bud.Window("claude", "seven_day", 40)]
    for i, cost in enumerate((4.3, 4.3, 1.5, 0.5, 0.9)):   # a busy first hour of real work
        p.db.x("INSERT INTO runs(role,provider,status,started,ended,cost_usd) VALUES('worker','claude','ok',?,?,?)",
               (now - 3000, now - 60 * i, cost))
        p.db.spend("claude", cost, f"task:{i}")
    assert bud.evaluate(p.db, p.config(), "claude", wins).level == "green"
    for cost in (4.0, 5.0):                                # the same hour, two runs that went nowhere
        p.db.x("INSERT INTO runs(role,provider,status,started,ended,cost_usd) VALUES('worker','claude','stalled',?,?,?)",
               (now - 2000, now - 30, cost))
    g = bud.evaluate(p.db, p.config(), "claude", wins)
    assert g.level == "red" and any("failed or stalled" in r for r in g.reasons)


def test_one_listener_per_chat(env):
    """The newest listener wins, and a listener whose starter is gone exits by itself."""
    p = make(env)
    p.db.x("INSERT INTO chats(id,created,label,last_active,last_read) VALUES('c1',?,?,?,0)",
           (time.time(), "t", time.time()))
    run_env = dict(os.environ, TTP_HOME=str(env["home"]), TTP_HOST="testhost")
    lock = p.state / "listen-c1.pid"
    cmd = [sys.executable, str(TTP), "listen", "demo", "--chat", "c1", "--timeout", "60"]
    first = subprocess.Popen(cmd, env=run_env, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    try:
        deadline = time.time() + 15
        while time.time() < deadline and not lock.exists():
            time.sleep(0.05)
        assert lock.exists(), "the first listener never took the chat"
        second = subprocess.Popen(cmd, env=run_env, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        try:
            first.wait(timeout=15)
            deadline = time.time() + 10     # the new listener writes its id just after the old one dies
            while time.time() < deadline and lock.exists() and lock.read_text().strip() != str(second.pid):
                time.sleep(0.05)
            assert lock.read_text().strip() == str(second.pid), "the newest listener does not own the chat"
            p.db.post("out", "hello", chat="c1", kind="reply")
            out = ""
            deadline = time.time() + 15
            while time.time() < deadline and "hello" not in out:
                time.sleep(0.05)
                out = p.db.one("SELECT last_read FROM chats WHERE id='c1'")["last_read"] and "hello" or ""
            assert out == "hello", "the newest listener did not receive the message"
        finally:
            second.terminate()
            second.wait(timeout=10)
    finally:
        if first.poll() is None:
            first.terminate()
            first.wait(timeout=10)
    # A listener whose parent dies (a lost background task, a dropped ssh session) exits on its own.
    starter = subprocess.run(["/bin/sh", "-c", " ".join(shlex.quote(x) for x in cmd) + " >/dev/null 2>&1 & echo $!; sleep 1"],
                             env=run_env, capture_output=True, text=True, timeout=30)
    orphan = int(starter.stdout.split()[0])
    deadline = time.time() + 15
    while time.time() < deadline:
        try:
            os.kill(orphan, 0)
        except OSError:
            break
        time.sleep(0.05)
    else:
        os.kill(orphan, 15)
        raise AssertionError("an orphaned listener kept running")


def test_newest_listener_claims_chat_before_old_one_exits(env):
    """The lock names the newest listener at once, even while an older one is slow to exit."""
    p = make(env)
    p.db.x("INSERT INTO chats(id,created,label,last_active,last_read) VALUES('c1',?,?,?,0)",
           (time.time(), "t", time.time()))
    run_env = dict(os.environ, TTP_HOME=str(env["home"]), TTP_HOST="testhost")
    lock = p.state / "listen-c1.pid"
    release = env["home"] / "release-old-listener"
    seen = env["home"] / "lock-at-sigterm"
    # Stands in for an older listener that is slow to shut down: when SIGTERM arrives it records
    # what the lock names, then exits only once the test creates the release file, so it is still
    # shutting down however slow the machine is.
    slow = ("import os,signal,sys,time\n"
            "def stop(*a):\n"
            f"    open({str(seen)!r}, 'w').write(open({str(lock)!r}).read())\n"
            "    end = time.time() + 60\n"
            f"    while not os.path.exists({str(release)!r}) and time.time() < end:\n"
            "        time.sleep(0.05)\n"
            "    sys.exit(0)\n"
            "signal.signal(signal.SIGTERM, stop)\n"
            "print('ready', flush=True)\n"
            "time.sleep(120)\n")
    old = subprocess.Popen([sys.executable, "-c", slow, "listen", "c1"], stdout=subprocess.PIPE, text=True)
    new = None
    try:
        assert old.stdout.readline().strip() == "ready"
        lock.write_text(str(old.pid))
        new = subprocess.Popen([sys.executable, str(TTP), "listen", "demo", "--chat", "c1", "--timeout", "60"],
                               env=run_env, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        # Generous: under load the new listener's interpreter start alone can take seconds.
        deadline = time.time() + 30
        while time.time() < deadline and lock.read_text().strip() != str(new.pid) and new.poll() is None:
            time.sleep(0.05)
        assert lock.read_text().strip() == str(new.pid), "the lock still names the older listener"
        assert old.poll() is None, "test premise: the older listener is still shutting down"
        release.touch()
        # It exits only through its SIGTERM handler, so this also shows the new listener stopped it.
        old.wait(timeout=30)
        assert lock.read_text().strip() == str(new.pid)
        # Ordering, not timing: the lock already named the new listener when the old one was told to stop.
        assert seen.read_text().strip() == str(new.pid), "the older listener was stopped before the claim"
    finally:
        for proc in (new, old):
            if proc and proc.poll() is None:
                proc.kill()
                proc.wait(timeout=10)


def test_process_checks_read_the_whole_command_line_under_a_narrow_terminal(env, monkeypatch):
    """`ps -o command=` cuts at $COLUMNS (80 under pytest-xdist, or a narrow terminal), so a long
    path hid 'listen' or 'daemon': an older listener was never replaced, a live daemon looked dead."""
    from ttp import cli, daemon
    monkeypatch.setenv("COLUMNS", "40")
    pad = "x" * 200
    child = subprocess.Popen([sys.executable, "-c", "import time; time.sleep(60)", pad,
                              "ttp", "listen", "demo", "--chat", "c1", "daemon"])
    try:
        assert cli._listener_alive(child.pid, "c1"), "the listener check read a cut command line"
        assert daemon._is_daemon(child.pid), "the daemon check read a cut command line"
    finally:
        child.kill()
        child.wait()


def test_listener_does_not_skip_a_reply_posted_between_its_reads(env, capsys):
    """A reply that lands after the unread query but before the high-water read is still shown."""
    p = make(env)
    p.db.x("INSERT INTO chats(id,created,label,last_active,last_read) VALUES('c1',?,?,?,0)",
           (time.time(), "t", time.time()))
    from types import SimpleNamespace
    from ttp.cli import _listen_loop
    db, real, posted = p.db, p.db.unread_for_chat, []

    def racy(*args, **kw):
        rows = real(*args, **kw)
        if not posted:
            posted.append(db.post("out", "late reply", chat="c1", kind="reply"))
        return rows
    db.unread_for_chat = racy
    _listen_loop(p, db, SimpleNamespace(chat="c1", timeout=3, once=True, ack=None), 0, "normal")
    assert "late reply" in capsys.readouterr().out, "the listener skipped a reply posted between its reads"


def test_listener_redelivers_until_acknowledged(env):
    """A listener killed after printing leaves the message unread; `--ack` is what marks it read."""
    import select
    p = make(env)
    p.db.x("INSERT INTO chats(id,created,label,last_active,last_read) VALUES('c1',?,?,?,0)",
           (time.time(), "t", time.time()))
    run_env = dict(os.environ, TTP_HOME=str(env["home"]), TTP_HOST="testhost")
    cmd = [sys.executable, str(TTP), "listen", "demo", "--chat", "c1"]
    mid = p.db.post("out", "important", chat="c1", kind="reply")
    first = subprocess.Popen(cmd + ["--ack", "0", "--timeout", "60"], env=run_env, stdout=subprocess.PIPE,
                             stderr=subprocess.PIPE, text=True)
    try:
        ready, _, _ = select.select([first.stdout], [], [], 15)
        assert ready, "the listener printed nothing"
        line = first.stdout.readline()
        assert "important" in line and f"#{mid}" in line, line
    finally:
        first.kill()
        first.wait(timeout=10)
    assert p.db.one("SELECT last_read FROM chats WHERE id='c1'")["last_read"] == 0
    again = subprocess.run(cmd + ["--once", "--ack", "0", "--timeout", "5"], env=run_env,
                           capture_output=True, text=True, timeout=30)
    assert "important" in again.stdout, "an unacknowledged message was not delivered again"
    done = subprocess.run(cmd + ["--once", "--ack", str(mid), "--timeout", "0.3"], env=run_env,
                          capture_output=True, text=True, timeout=30)
    assert "important" not in done.stdout, "an acknowledged message was delivered again"
    assert p.db.one("SELECT last_read FROM chats WHERE id='c1'")["last_read"] == mid



def test_listen_ack_is_clamped_to_known_messages(env):
    """An `--ack` past the newest message stops at it, and an older `--ack` never moves back."""
    p = make(env)
    p.db.x("INSERT INTO chats(id,created,label,last_active,last_read) VALUES('c1',?,?,?,0)",
           (time.time(), "t", time.time()))
    run_env = dict(os.environ, TTP_HOME=str(env["home"]), TTP_HOST="testhost")
    cmd = [sys.executable, str(TTP), "listen", "demo", "--chat", "c1", "--once", "--timeout", "0.3"]
    mid = p.db.post("out", "first", chat="c1", kind="reply")
    top = p.db.one("SELECT MAX(id) m FROM messages")["m"]
    subprocess.run(cmd + ["--ack", str(top + 1000)], env=run_env, capture_output=True, text=True, timeout=30)
    assert p.db.one("SELECT last_read FROM chats WHERE id='c1'")["last_read"] == top
    later = p.db.post("out", "second", chat="c1", kind="reply")
    assert later > top, "a future message would have been pre-acknowledged"
    subprocess.run(cmd + ["--ack", str(mid - 1)], env=run_env, capture_output=True, text=True, timeout=30)
    assert p.db.one("SELECT last_read FROM chats WHERE id='c1'")["last_read"] == top


def test_listen_honours_the_project_chat_floor(env):
    """notify.chat_min_severity filters broadcasts on every listener; a per-chat floor can only raise it."""
    p = make(env)
    p.db.x("INSERT INTO chats(id,created,label,last_active,last_read) VALUES('c1',?,?,?,0)",
           (time.time(), "t", time.time()))
    run_env = dict(os.environ, TTP_HOME=str(env["home"]), TTP_HOST="testhost")
    cmd = [sys.executable, str(TTP), "listen", "demo", "--chat", "c1", "--once", "--timeout", "0.3"]
    p.db.post("out", "routine note", kind="alert", severity="normal")
    p.set_config("notify.chat_min_severity", "high")
    out = subprocess.run(cmd, env=run_env, capture_output=True, text=True, timeout=30).stdout
    assert "routine note" not in out
    p.db.post("out", "urgent note", kind="alert", severity="high")
    out = subprocess.run(cmd, env=run_env, capture_output=True, text=True, timeout=30).stdout
    assert "urgent note" in out and "routine note" not in out


def test_config_refreshes_last_good_on_equal_mtime(env):
    """Two writes in one filesystem clock tick share an mtime; the newer config still becomes last-good."""
    p = make(env)
    p.set_config("budget.daily_usd", 42)
    p.config()
    good = p.state / "project.last-good.json"
    p.set_config("budget.daily_usd", 43)
    stamp = good.stat().st_mtime
    os.utime(p.config_path, (stamp, stamp))
    assert p.config()["budget"]["daily_usd"] == 43
    assert json.loads(good.read_text())["budget"]["daily_usd"] == 43

def test_web_chat_shows_replies_to_every_chat(env):
    p = make(env)
    from ttp import web
    p.db.x("INSERT INTO chats(id,created,label,last_active,last_read) VALUES('c1',?,?,?,0)",
           (time.time(), "laptop", time.time()))
