RENDER_HARNESS = r"""
const R = require(process.argv[1]);
const ops = [];
let writes = 0;
class El {
  constructor(tag) { this.tagName = tag; this.children = []; this.parent = null; this._inner = ""; this.textContent = ""; }
  set innerHTML(h) { writes++; this.children.forEach((c) => { c.parent = null; }); this.children = []; this._inner = h; }
  get innerHTML() { return this._inner; }
  contains(n) { for (; n; n = n.parent) if (n === this) return true; return false; }
  get firstElementChild() { return this.children[0] || null; }
  get nextElementSibling() { const s = this.parent ? this.parent.children : []; return s[s.indexOf(this) + 1] || null; }
  add(c) { c.parent = this; this.children.push(c); return c; }
  removeChild(c) { this.children.splice(this.children.indexOf(c), 1); c.parent = null; ops.push(["remove", c._ttpKey]); }
  replaceChild(n, c) { this.children[this.children.indexOf(c)] = n; n.parent = this; c.parent = null; ops.push(["replace", n._ttpKey]); }
  insertBefore(n, ref) {
    ops.push([n.parent ? "move" : "insert", n._ttpKey]);
    if (n.parent) n.parent.children.splice(n.parent.children.indexOf(n), 1);
    const i = ref ? this.children.indexOf(ref) : this.children.length;
    this.children.splice(i, 0, n); n.parent = this;
  }
}
R.make = (html) => { const n = new El("DIV"); n.html = html; return n; };
const none = { sel: [], active: null };
const rows = (o) => Object.keys(o).map((k) => ({ key: k, html: o[k] }));
const keys = (el) => el.children.map((c) => c._ttpKey);
const out = {};

// A section: unchanged HTML is not written again.
const sec = new El("DIV");
out.first = R.patch(sec, "<p>a</p>", none);
out.again = R.patch(sec, "<p>a</p>", none);
out.writes = writes;

// Rows: unchanged data writes nothing; one changed row replaces only that row.
const list = new El("DIV");
R.rows(list, rows({ 1: "a", 2: "b", 3: "c" }), none);
const [n1, n2, n3] = list.children;
ops.length = 0;
out.unchanged = R.rows(list, rows({ 1: "a", 2: "b", 3: "c" }), none);
out.unchanged_ops = ops.slice();
out.changed = R.rows(list, rows({ 1: "a", 2: "B", 3: "c" }), none);
out.kept_others = list.children[0] === n1 && list.children[2] === n3 && list.children[1] !== n2;
out.changed_html = list.children[1].html;

// A selection inside row 2: it is neither replaced nor moved, a new row still appears, and the
// held update lands once the selection clears.
const held2 = list.children[1], txt = held2.add(new El("#text"));
const sel = { sel: [txt, txt], active: null };
ops.length = 0;
out.sel_changed = R.rows(list, rows({ 0: "new", 1: "a", 2: "BB", 3: "c" }), sel);
out.sel_keys = keys(list);
out.sel_kept = list.children[2] === held2;
out.sel_ops = ops.slice();
out.sel_pending = R.pending();
R.flush(sel);
out.sel_still = list.children[2] === held2;
R.flush(none);
out.after_release = list.children[2] !== held2 && list.children[2].html === "BB";
out.after_pending = R.pending();

// A held row whose data is gone stays until released; other rows still reorder.
const held3 = list.children[3], t3 = held3.add(new El("#text"));
const reordered = [{ key: "0", html: "new" }, { key: "2", html: "BB" }, { key: "1", html: "a" }];
R.rows(list, reordered, { sel: [t3, t3], active: null });
out.gone_kept = list.children.indexOf(held3) >= 0;
out.reorder_held = keys(list);
R.flush(none);
out.reorder_after = keys(list);

// A reorder around a held row moves the others, never the held one; held rows that would swap wait.
const ord = new El("DIV"), seq = (...ks) => ks.map((k) => ({ key: k, html: k }));
R.rows(ord, seq("a", "b", "c"), none);
const hb = ord.children[1], tb = hb.add(new El("#text"));
ops.length = 0;
R.rows(ord, seq("b", "c", "a"), { sel: [tb, tb], active: null });
out.around = keys(ord);
out.around_moved = ops.filter((o) => o[0] === "move").map((o) => o[1]);
const ha = ord.children[2], ta = ha.add(new El("#text"));
R.rows(ord, seq("a", "b", "c"), { sel: [tb, ta], active: null });
out.swap_waits = keys(ord);
R.flush(none);
out.swap_after = keys(ord);

// An open <details> row stays open when its data changes.
list.children[0].open = true;
R.rows(list, [{ key: "0", html: "new!" }, { key: "2", html: "BB" }, { key: "1", html: "a" }], none);
out.still_open = list.children[0].open === true;

// A focused field inside a section holds the section until focus leaves.
const form = new El("DIV");
R.patch(form, "<input>", none);
const input = form.add(new El("INPUT"));
const w0 = writes;
out.focus = R.patch(form, "<input value=2>", { sel: [], active: input });
out.focus_writes = writes - w0;
out.focus_kept = form.children[0] === input;
R.flush(none);
out.blur = form.innerHTML;

// A payload that differs only in ticking fields has the same key.
const st = (now, age, title) => ({ now, heartbeat: { age }, push_queue: { entries: [{ age_s: age }] }, tasks: [{ id: 1, title }] });
out.same_key = R.key(st(1, 2, "x"), "m") === R.key(st(9, 30, "x"), "m");
out.new_key = R.key(st(1, 2, "x"), "m") !== R.key(st(1, 2, "y"), "m");
console.log(JSON.stringify(out));
"""


def test_web_render_keeps_unchanged_and_held_parts_of_the_page():
    """The web app's refresh writes only changed sections and rows, and never the one holding the
    user's text selection or focused field until they let go (render.js run under node)."""
    import json
    import shutil
    import subprocess
    node = shutil.which("node")
    if not node:
        pytest.skip("node not installed")
    r = subprocess.run([node, "-e", RENDER_HARNESS, str(RUNTIME / "ttp" / "web" / "render.js")],
                       capture_output=True, text=True, timeout=60)
    assert r.returncode == 0, r.stderr
    o = json.loads(r.stdout)
    assert (o["first"], o["again"], o["writes"]) == ("replaced", "same", 1), o
    assert o["unchanged"] == [] and o["unchanged_ops"] == [], o
    assert o["changed"] == ["2"] and o["kept_others"] and o["changed_html"] == "B", o
    # Under a selection the held row stays put; the new row is inserted around it.
    assert o["sel_changed"] == ["0"] and o["sel_keys"] == ["0", "1", "2", "3"] and o["sel_kept"], o
    assert o["sel_ops"] == [["insert", "0"]] and o["sel_pending"] == 1 and o["sel_still"], o
    assert o["after_release"] and o["after_pending"] == 0, o
    assert o["gone_kept"] and o["reorder_held"] == ["0", "2", "1", "3"], o
    assert o["reorder_after"] == ["0", "2", "1"], o
    assert o["around"] == ["b", "c", "a"] and "b" not in o["around_moved"], o
    assert o["swap_waits"] == ["b", "c", "a"] and o["swap_after"] == ["a", "b", "c"], o
    assert o["still_open"], o
    assert (o["focus"], o["focus_writes"], o["focus_kept"], o["blur"]) == ("held", 0, True, "<input value=2>"), o
    assert o["same_key"] and o["new_key"], o


def test_web_app_writes_the_page_through_render_js():
    """refresh() patches through render.js (no whole-section innerHTML resets, ages filled on the
    client) and the page loads render.js first."""
    web = RUNTIME / "ttp" / "web"
    js = (web / "app.js").read_text()
    body = js[js.index("async function refresh()"):js.index("window.setSched")]
    assert ".innerHTML" not in body and ".textContent =" not in body and "ago(" not in body.replace("ago(lastOk", ""), body
    assert "R.key(st" in body and "R.rows(" in body
    html = (web / "index.html").read_text()
    assert html.index('src="render.js"') < html.index('src="app.js"')

def _run_until(d, p, cond, timeout=60):
    deadline = time.time() + timeout
    while time.time() < deadline:
        d.cfg = p.config()
        d.tick()
        if cond():
            return True
        time.sleep(0.05)
    return False


def test_waiting_handoff_requeues_without_spending_an_attempt(env, monkeypatch):
    p = make(env)
    from ttp.daemon import Daemon
    monkeypatch.setenv("TTP_FAKE_RESULT", json.dumps(
        {"status": "waiting", "summary": "all boards reserved", "waiting_for": "a free board",
         "retry_after_s": 600}))
    tid = p.db.add_task("measure on a board", "needs a board", kind="work", tier="light", origin="user")
    d = Daemon(p.base)
    assert _run_until(d, p, lambda: p.db.task(tid)["status"] == "queued" and p.db.task(tid)["attempts"] == 0
                      and p.db.task(tid)["not_before"] and not p.db.q("SELECT id FROM runs WHERE status='running'"))
    t = p.db.task(tid)
    assert t["not_before"] > time.time() + 500, "the retry came too soon"
    assert "a free board" in (t["blocked_reason"] or "")
    assert json.loads(t["result"])["waits"] == 1


def test_a_wake_runs_at_light_or_its_wake_tier_never_above_the_task_and_other_runs_are_unchanged(
        env, monkeypatch):
    p = make(env)
    from ttp import daemon as dmod
    from ttp.db import dump_result
    d = dmod.Daemon(p.base)
    started = {}
    monkeypatch.setattr(d, "start_run", lambda role, prompt, provider, tier, cwd, **k: started.update(
        {k["task"]["id"]: (tier, k["note"].get("wake"), prompt)}))

    def task(tier, result=None):
        tid = p.db.add_task(f"t{len(started)}-{tier}-{result}", "s", kind="work", tier=tier, origin="user")
        if result:
            p.db.update_task(tid, result=dump_result({"summary": "earlier", **result}))
        return tid

    waits_for = task("standard", {"status": "waiting", "waiting_for": "a build"})
    probes = task("deep", {"status": "waiting", "retry_when": "test -e done"})
    asks_deep = task("standard", {"status": "waiting", "waiting_for": "a build", "wake_tier": "deep"})
    asks_std = task("deep", {"status": "waiting", "waiting_for": "a build", "wake_tier": "standard"})
    light_task = task("light", {"status": "waiting", "waiting_for": "a build", "wake_tier": "standard"})
    says_nothing = task("standard", {"status": "waiting"})
    never_waited = task("standard")
    failed_before = task("deep", {"status": "failed", "waiting_for": "a build"})
    for _ in range(4):   # a few start per tick
        d.dispatch()
    assert started[waits_for][:2] == ("light", {"tier": "light", "escalated": False})
    assert "this run: light wake" in started[waits_for][2] and 'wake_tier: "standard"' in started[waits_for][2]
    assert started[probes][:2] == ("light", {"tier": "light", "escalated": False})
    assert started[asks_deep][0] == "standard", "a wake_tier above the task's own tier is capped"
    assert started[asks_std][0] == "standard"
    assert started[light_task][0] == "light"
    assert started[says_nothing][:2] == ("standard", {"tier": "standard", "escalated": False})
    assert "retry_after_s: 0" not in started[says_nothing][2], "a wake at the task's tier has nothing to escalate"
    for tid, tier in ((never_waited, "standard"), (failed_before, "deep")):
        assert started[tid][:2] == (tier, None)
        assert " wake" not in started[tid][2].split("## Spec")[0]


def test_a_light_wake_escalates_once_at_once_and_free(env, monkeypatch):
    p = make(env)
    from ttp.daemon import Daemon
    from ttp.db import dump_result
    monkeypatch.setenv("TTP_FAKE_RESULT", json.dumps(
        {"status": "waiting", "summary": "the build is done; the measurements remain", "waiting_for": "nothing",
         "retry_after_s": 0, "wake_tier": "standard"}))
    tid = p.db.add_task("measure after the build", "s", kind="work", tier="standard", origin="user")
    p.db.update_task(tid, result=dump_result({"status": "waiting", "summary": "build started",
                                              "waiting_for": "the build", "waits": 2}))
    d = Daemon(p.base)

    def runs():
        return p.db.q("SELECT status, note FROM runs WHERE task=? AND role='worker' ORDER BY id", (tid,))

    assert _run_until(d, p, lambda: len(runs()) == 2 and p.db.task(tid)["status"] == "queued"
                      and all(r["status"] != "running" for r in runs()))
    wakes = [json.loads(r["note"])["wake"] for r in runs()]
    assert wakes == [{"tier": "light", "escalated": False}, {"tier": "standard", "escalated": True}]
    t = p.db.task(tid)
    # The escalated run asked again: that is an ordinary wait now, not a second free run.
    assert t["attempts"] == 0 and json.loads(t["result"])["waits"] == 3
    assert t["not_before"] > time.time() + 200
    assert not json.loads(t["result"]).get("escalated_wake")


def test_an_escalated_wake_that_keeps_a_retry_when_runs_only_once_its_probe_passes(env, monkeypatch):
    """A light wake that found work for after its probe passes escalates, but the probe says when:
    no escalated run while it says "not yet", one as soon as it exits 0."""
    p = make(env)
    from ttp import daemon as dmod
    from ttp.db import dump_result
    monkeypatch.setattr(dmod, "PROBE_EVERY_S", 0.2)
    flag = env["tmp"] / "built.flag"
    monkeypatch.setenv("TTP_FAKE_RESULT", json.dumps(
        {"status": "waiting", "summary": "measure once the build is done", "waiting_for": "the build",
         "retry_after_s": 0, "wake_tier": "standard", "retry_when": f"test -f {flag}"}))
    tid = p.db.add_task("measure after the build", "s", kind="work", tier="standard", origin="user")
    p.db.update_task(tid, result=dump_result({"status": "waiting", "summary": "build started",
                                              "waiting_for": "the build", "waits": 2}))
    d = dmod.Daemon(p.base)

    def runs():
        return p.db.q("SELECT status, note FROM runs WHERE task=? AND role='worker' ORDER BY id", (tid,))

    assert _run_until(d, p, lambda: len(runs()) == 1 and p.db.task(tid)["status"] == "queued"
                      and runs()[0]["status"] != "running")
    t = p.db.task(tid)
    res = json.loads(t["result"])
    assert res.get("escalated_wake") and "woke" not in res and res["waits"] == 2
    assert t["not_before"] > time.time() and "once its probe passes" in t["blocked_reason"]
    assert not _run_until(d, p, lambda: len(runs()) > 1, timeout=1.5), "no escalated run while it says not yet"
    flag.write_text("")
    monkeypatch.delenv("TTP_FAKE_RESULT")
    assert _run_until(d, p, lambda: len(runs()) == 2)
    assert json.loads(runs()[1]["note"])["wake"] == {"tier": "standard", "escalated": True}


def test_a_mechanical_next_step_wakes_at_light_and_that_run_finishes_it(env, monkeypatch):
    """A review whose detached checks finished, with only its push left (next_step), takes one light
    run that pushes and is done: no light check plus a rerun at the task's tier and effort."""
    p = make(env)
    from ttp import budget as bud
    from ttp.daemon import Daemon
    from ttp.db import dump_result
    wait = {"status": "waiting", "summary": "checks started", "waiting_for": "the checks", "wake_tier": "standard"}
    assert bud.wake_tier("standard", {**wait, "next_step": "push"}) == "light", "next_step outranks wake_tier"
    assert bud.wake_tier("deep", {"status": "waiting", "next_step": "push"}) == "light"
    assert bud.wake_tier("standard", wait) == "standard"
    assert bud.wake_tier("standard", {**wait, "next_step": "  "}) == "standard", "a blank step is no step"
    esc = {"status": "waiting", "retry_after_s": 0, "wake_tier": "standard", "next_step": "push",
           "escalated_wake": True}
    assert bud.wake_tier("standard", esc) == "standard", "an escalated wake runs at the task's tier"
    monkeypatch.setenv("TTP_FAKE_RESULT", json.dumps({"status": "done", "summary": "checks green; pushed"}))
    tiers = {"light": {"effort": "low"}, "standard": {"effort": "high"}, "deep": {"effort": "max"}}
    p.set_config("providers.fake.tiers", tiers)
    mech = p.db.add_task("review and push", "s", kind="work", tier="standard", origin="user")
    p.db.update_task(mech, result=dump_result({**wait, "next_step": "push"}))
    plain = p.db.add_task("review and push, unmarked", "s", kind="work", tier="standard", origin="user")
    p.db.update_task(plain, result=dump_result(wait))
    d = Daemon(p.base)

    def runs(tid):
        return p.db.q("SELECT status, effort, note FROM runs WHERE task=? AND role='worker' ORDER BY id", (tid,))

    assert _run_until(d, p, lambda: all(p.db.task(t)["status"] == "done" for t in (mech, plain)))
    (one,) = runs(mech)
    assert json.loads(one["note"])["wake"] == {"tier": "light", "escalated": False}
    assert one["effort"] == "low"
    (other,) = runs(plain)
    assert json.loads(other["note"])["wake"]["tier"] == "standard"
    assert other["effort"] == "high"
    assert p.db.task(mech)["attempts"] == 1


def test_a_mechanical_wake_that_escalates_but_keeps_next_step_reruns_at_the_tasks_tier(env, monkeypatch):
    """A light run for a mechanical step that hit a conflict escalates; if it keeps next_step in its
    hand-off, the escalated rerun still runs at the task's tier and effort, not light again."""
    p = make(env)
    from ttp.daemon import Daemon
    from ttp.db import dump_result
    monkeypatch.setenv("TTP_FAKE_RESULT", json.dumps(
        {"status": "waiting", "summary": "the rebase conflicts", "waiting_for": "nothing", "retry_after_s": 0,
         "wake_tier": "standard", "next_step": "push"}))
    p.set_config("providers.fake.tiers", {"light": {"effort": "low"}, "standard": {"effort": "high"},
                                          "deep": {"effort": "max"}})
    tid = p.db.add_task("review and push", "s", kind="work", tier="standard", origin="user")
    p.db.update_task(tid, result=dump_result({"status": "waiting", "summary": "checks started",
                                              "waiting_for": "the checks", "next_step": "push"}))
    d = Daemon(p.base)

    def runs():
        return p.db.q("SELECT status, effort, note FROM runs WHERE task=? AND role='worker' ORDER BY id", (tid,))

    assert _run_until(d, p, lambda: len(runs()) == 2 and all(r["status"] != "running" for r in runs()))
    assert [json.loads(r["note"])["wake"] for r in runs()] == [
        {"tier": "light", "escalated": False}, {"tier": "standard", "escalated": True}]
    assert [r["effort"] for r in runs()] == ["low", "high"]


def test_a_mechanical_wake_prompt_says_to_do_the_step_and_a_refused_wake_keeps_it(env):
    p = make(env)
