    before = p.db.one("SELECT COUNT(*) n FROM tasks")["n"]
    for deps, why in (([999], "no task #999"), ([ok, gone], f"#{gone} which is cancelled"), ("x", "must be a list")):
        problems = coord.apply(p, [{"type": "task_add", "title": f"new {why}", "depends_on": deps}])
