    p.set_config("coordinator.ask_timeout_h", 0)
    assert coord.expire_asks(p, now=late) == []
    assert coord.apply(p, [{"type": "config_set", "key": "coordinator.ask_timeout_h", "value": "24"}]) == []
    assert coord.expire_asks(p, now=late) == []
