def _conflicting_upgrade(env, monkeypatch):
    """A project whose harness prompt conflicts with the installed template; restarts are recorded."""
    p = make(env)
    from ttp import service
    restarts = []
    monkeypatch.setattr(service, "restart", lambda p: restarts.append(1) or "restarted")
    (p.harness / "prompts" / "kind-harness.md").write_text("# Harness task, this project's way\n")
    _git_out(p.harness, "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qam", "local prompt")
    _install_template(env, {"kind-harness.md": "# Harness task, upstream's way\n"})
    return p, restarts


def test_an_upgrade_settles_conflicts_that_need_no_judgment_without_a_task(env, monkeypatch, capsys):
    """Both sides added a section at one spot, or upstream ships the project's own fix: `ttp upgrade`
    finishes the merge itself and queues no model task."""
    p = make(env)
    from ttp import cli, service
    restarts = []
    monkeypatch.setattr(service, "restart", lambda p: restarts.append(1) or "restarted")
    h = p.harness
    worker = (h / "prompts" / "worker.md").read_text()
    review = (h / "prompts" / "kind-harness.md").read_text()
    (h / "prompts" / "worker.md").write_text(worker + "\n## Long waits\nThis project's own rule.\n")
    (h / "prompts" / "kind-harness.md").write_text(review + "Never edit the live harness.\n")
    _git_out(h, "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qam", "local prompts")
    _install_template(env, {"worker.md": worker + "\n## Shared clusters\nUpstream's new rule.\n",
                            "kind-harness.md": review + "Never edit the live harness.\nCheck it first.\n"})
    cli.main(["upgrade", "demo"])
    out = capsys.readouterr().out
    assert "settled the template merge's conflicts" in out and "worker.md" in out
    text = (h / "prompts" / "worker.md").read_text()
    assert text.index("This project's own rule.") < text.index("Upstream's new rule.") and "<<<<<<<" not in text
    assert (h / "prompts" / "kind-harness.md").read_text() == review + "Never edit the live harness.\nCheck it first.\n"
    assert restarts == [1] and not p.db.q("SELECT id FROM tasks WHERE kind='harness'")
    assert not _git_out(h, "status", "--porcelain") and len(_git_out(h, "worktree", "list").splitlines()) == 1


def test_a_conflicting_upgrade_queues_at_most_one_task_a_day(env, monkeypatch, capsys):
    """Each release would otherwise queue its own model task for the same conflict: within a day of
    the last one, the upgrade only records that it waits, and the daemon tries again after."""
    from ttp import cli, release
    p, restarts = _conflicting_upgrade(env, monkeypatch)
    with pytest.raises(SystemExit):
        cli.main(["upgrade", "demo"])
    first = p.db.one("SELECT id FROM tasks WHERE kind='harness'")["id"]
    p.db.update_task(first, status="done")
    _next_release(env)      # the next release, the same conflict
    capsys.readouterr()
    with pytest.raises(SystemExit) as e:
        cli.main(["upgrade", "demo"])
    out = capsys.readouterr().out
    assert e.value.code == 75 and f"Harness task #{first} took on a template merge" in out
    assert "upgrade deferred" in out and "tries again after" in out
    assert [t["id"] for t in p.db.q("SELECT id FROM tasks WHERE kind='harness'")] == [first] and not restarts
    rec = p.db.kv(release.KV_AUTO)
    assert rec["outcome"] == "deferred" and rec["key"].endswith(" bbbb2222") and rec["until"] > time.time()
    d = {"key": rec["key"]}
    assert "less than a day ago" in release.hold_reason(p, d)
    p.db.set_kv(release.KV_RELEASE, {"installed": "x (bbbb2222)", "current": "y", "key": rec["key"], "newer": True})
    assert "next try after" in release.line(p, p.db, {})
    # a day later the conflict gets a task of its own again
    p.db.x("UPDATE tasks SET created=created-? WHERE id=?", (release.TASK_EVERY_S + 60, first))
    p.db.set_kv(release.KV_AUTO, {**rec, "until": time.time() - 1})
    assert release.hold_reason(p, d) == ""
    with pytest.raises(SystemExit):
        cli.main(["upgrade", "demo"])
    assert len(p.db.q("SELECT id FROM tasks WHERE kind='harness'")) == 2


def _next_release(env, newer=True):
    """The installed release becomes the next one: a new source commit and, with `newer`, a numerically
    newer version (the only drift the daemon retries)."""
    import re
    runtime = env["home"] / "lib" / "current" / "runtime" / "ttp"
    (runtime / "SOURCE_COMMIT").write_text("bbbb2222\n")
    if newer:
        init = runtime / "__init__.py"
        init.write_text(re.sub(r'__version__ = "(\d+)\.(\d+)\.(\d+)"',
                               lambda m: f'__version__ = "{m[1]}.{m[2]}.{int(m[3]) + 1}"', init.read_text(), 1))


def _deferred_conflict(env, monkeypatch, name="demo", newer=True):
    """A project whose template merge conflicts again within a day of its last harness task (done)."""
    import shutil
    from ttp import cli
    if name != "demo":      # one project per repository
        shutil.copytree(env["repo"], env["tmp"] / f"repo-{name}", symlinks=True)
        env = {**env, "repo": env["tmp"] / f"repo-{name}"}
    p = make(env, name)
    from ttp import service
    monkeypatch.setattr(service, "restart", lambda p: pytest.fail("a conflicting upgrade restarted the daemon"))
    (p.harness / "prompts" / "kind-harness.md").write_text("# Harness task, this project's way\n")
    _git_out(p.harness, "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qam", "local prompt")
    _install_template(env, {"kind-harness.md": "# Harness task, upstream's way\n"})
    with pytest.raises(SystemExit):
        cli.main(["upgrade", name])
    first = p.db.one("SELECT id FROM tasks WHERE kind='harness'")["id"]
    p.db.update_task(first, status="done")
    _next_release(env, newer)
    return p, first


def test_a_conflict_handed_to_a_harness_task_is_deferred_with_exit_75(env, monkeypatch, capsys):
    """The project's own harness task takes the merge on: nothing failed, so a deploy counts it as deferred."""
    from ttp import cli
    p, restarts = _conflicting_upgrade(env, monkeypatch)
    with pytest.raises(SystemExit) as e:
        cli.main(["upgrade", "demo"])
    tid = p.db.one("SELECT id FROM tasks WHERE kind='harness'")["id"]
    assert e.value.code == 75 and f"Harness task #{tid} finishes it" in capsys.readouterr().out and not restarts


def test_a_conflict_nothing_retries_with_upgrade_auto_off_exits_1(env, monkeypatch, capsys):
    """upgrade.auto off and no open harness task: nobody takes the merge on, so it is a failure."""
    from ttp import cli
    p, first = _deferred_conflict(env, monkeypatch)
    p.set_config("upgrade.auto", False)
    capsys.readouterr()
    with pytest.raises(SystemExit) as e:
        cli.main(["upgrade", "demo"])
    out = capsys.readouterr().out
    assert e.value.code == 1 and "upgrade.auto is off, so nothing retries it" in out and "deferred" not in out
    assert [t["id"] for t in p.db.q("SELECT id FROM tasks WHERE kind='harness'")] == [first]


def test_a_conflict_on_a_newer_version_is_deferred_as_the_daemon_retries_it(env, monkeypatch, capsys):
    from ttp import cli, release
    p, first = _deferred_conflict(env, monkeypatch)
    assert release.retried(release.drift(p), p.config()), "the daemon's own gate"
    capsys.readouterr()
    with pytest.raises(SystemExit) as e:
        cli.main(["upgrade", "demo"])
    out = capsys.readouterr().out
    assert e.value.code == 75 and "upgrade deferred" in out and "tries again after" in out


def test_a_same_version_conflict_from_another_commit_is_a_failure_nothing_retries(env, monkeypatch, capsys):
    """The daemon retries only a newer version: a branch tip with no version bump that conflicts within
    a day of the last harness task is never retried, so it must not be counted as deferred."""
    from ttp import cli, release
    p, first = _deferred_conflict(env, monkeypatch, newer=False)
    assert release.drift(p) and not release.retried(release.drift(p), p.config()), "the daemon's own gate"
    capsys.readouterr()
    with pytest.raises(SystemExit) as e:
        cli.main(["upgrade", "demo"])
    out = capsys.readouterr().out
    assert e.value.code == 1 and "deferred" not in out and "nothing retries it" in out
    assert "retries only a newer version" in out and "rerun `ttp upgrade demo` after" in out
    assert [t["id"] for t in p.db.q("SELECT id FROM tasks WHERE kind='harness'")] == [first]


def test_a_deploy_counts_deferred_upgrades_and_still_reports_a_real_failure(env, monkeypatch, tmp_path):
    """An after_push deploy that upgrades every project, counting exit 75 as deferred: a conflict its
    project retries itself fails nothing; one that nobody takes on, next to it, is still reported."""
    _deferred_conflict(env, monkeypatch, "alpha")
    beta, _ = _deferred_conflict(env, monkeypatch, "beta")
    deploy = tmp_path / "deploy.sh"
    deploy.write_text(
        'failed=""\n'
        'for p in "$@"; do\n'
        f'  "{sys.executable}" "{TTP}" upgrade "$p"; e=$?\n'
        '  if [ $e -eq 0 ]; then :\n'
        '  elif [ $e -eq 75 ]; then echo "deploy: $p deferred"\n'
        '  else echo "deploy: $p failed (exit $e)"; failed="$failed $p"; fi\n'
        'done\n'
        '[ -z "$failed" ] || { echo "upgrade failed for:$failed"; exit 1; }\n')
    plain = {k: v for k, v in os.environ.items() if k != "PYTHONPATH"}
    r = subprocess.run(["sh", str(deploy), "alpha"], capture_output=True, text=True, env=plain)
    assert r.returncode == 0 and "deploy: alpha deferred" in r.stdout and "failed" not in r.stdout, r
    beta.set_config("upgrade.auto", False)
    r = subprocess.run(["sh", str(deploy), "alpha", "beta"], capture_output=True, text=True, env=plain)
    assert r.returncode == 1 and "deploy: alpha deferred" in r.stdout, r
    assert "deploy: beta failed (exit 1)" in r.stdout and "upgrade failed for: beta" in r.stdout, r


def _stuck_events(p):
    return p.db.q("SELECT severity, text FROM events WHERE source='upgrade' AND kind='observation'")


def test_the_same_deferred_conflict_past_48h_is_reported_once_as_a_normal_observation(env, monkeypatch, capsys):
    """Every push's deploy defers the same conflict quietly; once it has lasted past 48 h the coordinator
    hears of it once, at normal severity, and the deferrals after that (also while a harness task holds
    the upgrade) add nothing."""
    from ttp import cli, release
    p, first = _deferred_conflict(env, monkeypatch)
    for _ in range(2):
        with pytest.raises(SystemExit) as e:
            cli.main(["upgrade", "demo"])
        assert e.value.code == 75
    rec = p.db.kv(release.KV_STUCK)
    assert rec["sig"] == "conflicts in prompts/kind-harness.md" and rec["tasks"] == [first] and not _stuck_events(p)
    p.db.set_kv(release.KV_STUCK, {**rec, "first": time.time() - release.STUCK_AFTER_S - 3600})
    with pytest.raises(SystemExit):
        cli.main(["upgrade", "demo"])
    ev = _stuck_events(p)
    assert len(ev) == 1 and ev[0]["severity"] == "normal", ev
    assert "2.0 days" in ev[0]["text"] and "prompts/kind-harness.md" in ev[0]["text"]
    with pytest.raises(SystemExit):
        cli.main(["upgrade", "demo"])
    tid = p.db.add_task(release.UPGRADE_TASK_TITLE, "merge", kind="harness")
    with pytest.raises(SystemExit) as e:      # an open harness task holds it: no merge runs, still quiet
        cli.main(["upgrade", "demo"])
    assert e.value.code == 75 and len(_stuck_events(p)) == 1 and tid in p.db.kv(release.KV_STUCK)["tasks"]


def test_two_failed_harness_retries_of_the_same_conflict_are_reported_once(env, monkeypatch, capsys):
    """Well inside 48 h, the second harness task that ends without landing the merge reports it once."""
    from ttp import cli, release
    p, _ = _conflicting_upgrade(env, monkeypatch)
    tids = []
    for n in range(4):
        with pytest.raises(SystemExit):
            cli.main(["upgrade", "demo"])
        tid = p.db.one("SELECT id FROM tasks WHERE kind='harness' ORDER BY id DESC")["id"]
        if tid not in tids:
            tids.append(tid)
        assert len(_stuck_events(p)) == (1 if n >= 2 else 0), n
        p.db.update_task(tid, status="failed")
        p.db.x("UPDATE tasks SET created=? WHERE id=?", (time.time() - 2 * release.TASK_EVERY_S, tid))
    assert len(tids) == 4
    text = _stuck_events(p)[0]["text"]
    assert f"#{tids[0]}, #{tids[1]} ended without landing it" in text and "0.0 days" in text


def test_a_landed_upgrade_or_another_conflict_starts_the_stuck_clock_over(env, monkeypatch, capsys):
    from ttp import cli, release
    p, restarts = _conflicting_upgrade(env, monkeypatch)
    release.note_deferred(p, "the merge conflicts in prompts/a.md, prompts/b.md", 7)
    old = p.db.kv(release.KV_STUCK)
    release.note_deferred(p, "the merge conflicts in prompts/b.md, prompts/a.md")       # same files
    assert p.db.kv(release.KV_STUCK)["first"] == old["first"] and p.db.kv(release.KV_STUCK)["tasks"] == [7]
    release.note_deferred(p, "the merged runtime fails `python -c x`: line 12")
    rec = p.db.kv(release.KV_STUCK)
    assert rec["first"] > old["first"] and rec["tasks"] == [] and rec["sig"].endswith("line #")
    # The project settles the conflict its own way; the next upgrade lands and nothing is outstanding.
    (p.harness / "prompts" / "kind-harness.md").write_text("# Harness task, upstream's way\n")
    _git_out(p.harness, "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qam", "take upstream's")
    cli.main(["upgrade", "demo"])
    assert restarts and p.db.kv(release.KV_STUCK) is None and not _stuck_events(p)


def test_a_second_upgrade_is_refused_while_one_holds_the_harness_upgrade_lock(env, monkeypatch):
    from ttp import cli, locks, release, service
    p = make(env)
    monkeypatch.setattr(service, "restart", lambda p: "restarted")
    _install_template(env)
    (env["home"] / "lib" / "current" / "runtime" / "ttp" / "SOURCE_COMMIT").write_text("abc1234\n")
    assert release.upgrade_lock(p) == locks.slot_paths(p.state / "locks", "harness-upgrade", 1)[0], \
        "the same lock `ttp lock harness-upgrade` takes"
    before = _git_out(p.harness, "rev-parse", "HEAD")
    held = locks.try_take([release.upgrade_lock(p)], "ttp upgrade (pid 1)", "ttp upgrade")
    try:
        with pytest.raises(SystemExit) as e:
            cli.main(["upgrade", "demo"])
        assert e.value.code == 75
        assert _git_out(p.harness, "rev-parse", "HEAD") == before
        assert _git_out(p.harness, "rev-parse", "upstream") != "" and not p.db.q("SELECT id FROM tasks")
    finally:
        held.close()
    cli.main(["upgrade", "demo"])
    assert _git_out(p.harness, "rev-parse", "HEAD") != before


def test_the_upgrade_lock_is_released_after_a_failed_a_crashed_and_a_successful_upgrade(env, monkeypatch):
    from ttp import cli, locks, release
    p, restarts = _conflicting_upgrade(env, monkeypatch)

    def free():
        f = locks.try_take([release.upgrade_lock(p)], "test")
        return f is not None and (f.close() or True)
    with pytest.raises(SystemExit):
        cli.main(["upgrade", "demo"])                   # conflicts: queues a task
    assert free() and p.db.one("SELECT id FROM tasks WHERE kind='harness'")
    p.db.update_task(p.db.one("SELECT id FROM tasks")["id"], status="cancelled")
    real = cli._merge_upstream
    monkeypatch.setattr(cli, "_merge_upstream", lambda *a, **k: (_ for _ in ()).throw(RuntimeError("boom")))
    with pytest.raises(RuntimeError):
        cli.main(["upgrade", "demo"])
    assert free(), "an error mid-merge must not wedge the project"
    monkeypatch.setattr(cli, "_merge_upstream", real)
    _install_template(env, {"kind-harness.md": "# Harness task, this project's way\n"})
    cli.main(["upgrade", "demo"])
    assert restarts == [1] and free()


def test_an_upgrade_whose_main_moved_under_the_merge_does_not_commit(env, monkeypatch):
    """A second process changed the template's files on main while the upgrade merged: the checked
    merge would drop that change, so the upgrade stops and reports instead."""
    from ttp import cli, service
    p = make(env)
    restarts = []
    monkeypatch.setattr(service, "restart", lambda p: restarts.append(1) or "restarted")
    h = p.harness
    worker = (RUNTIME.parent / "template" / "prompts" / "worker.md").read_text()
    _install_template(env, {"worker.md": worker + "\nupstream line\n"})
    real = cli._merge_upstream

    def racing(*a, **k):
        out = real(*a, **k)
        (h / "runtime" / "ttp" / "local_wiring.py").write_text("LOCAL = True\n")
        _git_out(h, "-c", "user.name=t", "-c", "user.email=t@t", "add", "-A")
        _git_out(h, "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "local wiring")
        return out
    monkeypatch.setattr(cli, "_merge_upstream", racing)
    with pytest.raises(SystemExit) as e:
        cli.main(["upgrade", "demo"])
    assert e.value.code == 1 and not restarts
    assert _git_out(h, "log", "-1", "--format=%s") == "local wiring"
    assert "upstream line" not in (h / "prompts" / "worker.md").read_text()
    # A charter or memory commit of the daemon meanwhile is kept, and the upgrade goes through.
    monkeypatch.setattr(cli, "_merge_upstream", lambda *a, **k: (
        out := real(*a, **k), (h / "CHARTER.md").write_text("# changed\n"),
        _git_out(h, "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qam", "charter"))[0])
    cli.main(["upgrade", "demo"])
    assert "upstream line" in (h / "prompts" / "worker.md").read_text() and restarts == [1]
    assert (h / "CHARTER.md").read_text() == "# changed\n" and (h / "runtime" / "ttp" / "local_wiring.py").exists()


def test_only_the_upgrade_task_applies_its_merge_and_a_hand_merge_of_upstream_is_refused(env, monkeypatch, tmp_path):
    from ttp import cli
    p, restarts = _conflicting_upgrade(env, monkeypatch)
    h = p.harness
    with pytest.raises(SystemExit):
        cli.main(["upgrade", "demo"])
    tid = p.db.one("SELECT id FROM tasks WHERE kind='harness'")["id"]
    before = _git_out(h, "rev-parse", "HEAD")
    ident = ["-c", "user.name=t", "-c", "user.email=t@t"]
    # A second process merges upstream into the live main by hand: git refuses, main stays.
    r = subprocess.run(["git", "-C", str(h), *ident, "merge", "-X", "theirs", "--no-edit", "upstream"],
                       capture_output=True, text=True)
    assert r.returncode != 0 and "only `ttp upgrade`" in r.stderr
    assert _git_out(h, "rev-parse", "HEAD") == before
    subprocess.run(["git", "-C", str(h), "merge", "--abort"], capture_output=True)
    subprocess.run(["git", "-C", str(h), "reset", "-q", "--hard", before], capture_output=True)
    # The task resolves in its own worktree, keeping the project's intent.
    wt = tmp_path / "merge"
    _git_out(h, "worktree", "add", "-q", "--detach", str(wt), "main")
    subprocess.run(["git", "-C", str(wt), *ident, "merge", "upstream"], capture_output=True)
    (wt / "prompts" / "kind-harness.md").write_text("# Harness task, this project's way\n")
    _git_out(wt, "add", "-A")
    _git_out(wt, *ident, "commit", "-qm", "merge upstream")
    merged = _git_out(wt, "rev-parse", "HEAD")
    monkeypatch.delenv("TTP_TASK", raising=False)
    for argv in (["upgrade", "demo"], ["upgrade", "demo", "--apply", merged]):   # not the task's run
        with pytest.raises(SystemExit) as e:
            cli.main(argv)
        assert e.value.code == 75 and _git_out(h, "rev-parse", "HEAD") == before
    monkeypatch.setenv("TTP_TASK", str(tid))
    with pytest.raises(SystemExit) as e:
        cli.main(["upgrade", "demo"])                  # the task applies its own resolution, not a new one
    assert e.value.code == 2
    # main moved since the task merged: --apply stops instead of overwriting it.
    (h / "prompts" / "worker.md").write_text("local rule\n")
    _git_out(h, *ident, "commit", "-qam", "local rule")
    moved = _git_out(h, "rev-parse", "HEAD")
    with pytest.raises(SystemExit) as e:
        cli.main(["upgrade", "demo", "--apply", merged])
    assert e.value.code == 1 and _git_out(h, "rev-parse", "HEAD") == moved and not restarts
    subprocess.run(["git", "-C", str(wt), *ident, "merge", "--no-edit", "main"], capture_output=True, check=True)
    merged = _git_out(wt, "rev-parse", "HEAD")
    cli.main(["upgrade", "demo", "--apply", merged])
    assert _git_out(h, "rev-parse", "HEAD") == merged and restarts == [1]
    assert (h / "prompts" / "worker.md").read_text() == "local rule\n"


def _upstream_version(h):
    import re
    return re.search(r'__version__ = "([^"]+)"', _git_out(h, "show", "upstream:runtime/ttp/__init__.py"))[1]


def test_a_newer_release_retargets_the_open_finish_task_instead_of_queuing_another(env, monkeypatch, tmp_path, capsys):
    """Release after release while one harness task finishes the merge: the same task takes each on
    (its spec, its running worker and `upstream` move to the newest), main is never merged into, and
    a merge the task made against the older template can no longer be applied."""
    from ttp import cli, release
    p, restarts = _conflicting_upgrade(env, monkeypatch)
    h = p.harness
    with pytest.raises(SystemExit):
        cli.main(["upgrade", "demo"])
    tid = p.db.one("SELECT id FROM tasks WHERE kind='harness'")["id"]
    first = release.finish_holder(p)
    assert first["task"] == tid and "Target release: tt-project " in p.db.task(tid)["spec"]
    before = _git_out(h, "rev-parse", "HEAD")
    run_dir = tmp_path / "run"
    run_dir.mkdir()
    p.db.x("INSERT INTO runs(task, role, status, dir, started) VALUES(?,?,?,?,?)",
           (tid, "worker", "running", str(run_dir), time.time()))
    ident = ["-c", "user.name=t", "-c", "user.email=t@t"]
    wt = tmp_path / "merge"      # the task's merge against the older template
    _git_out(h, "worktree", "add", "-q", "--detach", str(wt), "main")
    subprocess.run(["git", "-C", str(wt), *ident, "merge", "upstream"], capture_output=True)
    (wt / "prompts" / "kind-harness.md").write_text("# Harness task, this project's way\n")
    _git_out(wt, "add", "-A")
    _git_out(wt, *ident, "commit", "-qm", "merge upstream")
    old_merge = _git_out(wt, "rev-parse", "HEAD")
    _next_release(env)
    new_v = release.runtime_version(env["home"] / "lib" / "current" / "runtime")
    monkeypatch.delenv("TTP_TASK", raising=False)
    capsys.readouterr()
    with pytest.raises(SystemExit) as e:
        cli.main(["upgrade", "demo"])
    assert e.value.code == 75 and f"#{tid} is finishing the template merge and now targets" in capsys.readouterr().out
    assert [t["id"] for t in p.db.q("SELECT id FROM tasks WHERE kind='harness'")] == [tid]
    spec = p.db.task(tid)["spec"]
    assert f"Target release: tt-project {new_v} (bbbb2222)" in spec and spec.count("Target release:") == 1
    assert spec.count("Retargeted to") == 1 and "Retargeted to" in (run_dir / "steer.md").read_text()
    assert _git_out(h, "rev-parse", "HEAD") == before and not restarts and _upstream_version(h) == new_v
    assert release.finish_holder(p) == {"task": tid, "key": f"{new_v} bbbb2222", "target": f"{new_v} (bbbb2222)"}
    with pytest.raises(SystemExit) as e:        # the same release again: nothing new to tell the task
        cli.main(["upgrade", "demo"])
    assert e.value.code == 75 and p.db.task(tid)["spec"] == spec
    assert (run_dir / "steer.md").read_text().count("Retargeted to") == 1
    monkeypatch.setenv("TTP_TASK", str(tid))
    with pytest.raises(SystemExit) as e:        # the task's merge of the older template is not applied
        cli.main(["upgrade", "demo", "--apply", old_merge])
    assert e.value.code == 1 and _git_out(h, "rev-parse", "HEAD") == before and not restarts
    subprocess.run(["git", "-C", str(wt), *ident, "merge", "--no-edit", "upstream"], capture_output=True)
    (wt / "prompts" / "kind-harness.md").write_text("# Harness task, this project's way\n")
    _git_out(wt, "add", "-A")
    subprocess.run(["git", "-C", str(wt), *ident, "commit", "-qm", "merge the newer upstream"], capture_output=True)
    cli.main(["upgrade", "demo", "--apply", _git_out(wt, "rev-parse", "HEAD")])
    assert release.runtime_version(h / "runtime") == new_v and restarts == [1]


@pytest.mark.parametrize("end", ["done", "failed", "cancelled", "gone"])
def test_the_finish_task_locks_the_live_harness_until_it_ends(env, monkeypatch, end):
    """While the finish task is open no other upgrade merges into main, not even one that would merge
    cleanly now, and no other task applies a merge. Its end releases the lock, also when that end was
    recorded by a restart after a crash (the record outlives every process) or the task is gone."""
    from ttp import cli, release
    p, restarts = _conflicting_upgrade(env, monkeypatch)
    h = p.harness
    with pytest.raises(SystemExit):
        cli.main(["upgrade", "demo"])
    tid = p.db.one("SELECT id FROM tasks WHERE kind='harness'")["id"]
    before = _git_out(h, "rev-parse", "HEAD")
    assert release.finish_lock(p).is_file()
    # Upstream now agrees with the project: the merge would be clean, but the task holds the harness.
    _install_template(env, {"kind-harness.md": "# Harness task, this project's way\n"})
    monkeypatch.delenv("TTP_TASK", raising=False)
    with pytest.raises(SystemExit) as e:
        cli.main(["upgrade", "demo"])
    assert e.value.code == 75 and _git_out(h, "rev-parse", "HEAD") == before and not restarts
    other = p.db.add_task("Another harness task", "x", kind="harness")
    monkeypatch.setenv("TTP_TASK", str(other))
    with pytest.raises(SystemExit) as e:
        cli.main(["upgrade", "demo", "--apply", "upstream"])
    assert e.value.code == 75 and _git_out(h, "rev-parse", "HEAD") == before
    monkeypatch.delenv("TTP_TASK", raising=False)
    # A crash and a restart: the task is back in the queue, so it still holds the harness.
    p.db.update_task(tid, status="queued")
    assert release.finish_holder(p)["task"] == tid and release.hold_reason(p, {"key": release.finish_holder(p)["key"]})
    if end == "gone":
        p.db.x("DELETE FROM tasks WHERE id=?", (tid,))
    else:
        p.db.update_task(tid, status=end)
    assert release.finish_holder(p) is None and release.finish_lock(p).is_file()   # stale: counts as released
    cli.main(["upgrade", "demo"])
    assert restarts == [1] and not release.finish_lock(p).exists()     # cleaned under the upgrade lock


def test_with_no_open_finish_task_a_conflict_queues_a_task_that_takes_the_lock(env, monkeypatch, capsys):
    """No open finish task: a conflict queues one as before (exit 75) and only then is the harness held;
    once it ended more than a day ago, the next conflict queues a new task that takes the lock over."""
    from ttp import cli, release
    p, restarts = _conflicting_upgrade(env, monkeypatch)
    assert release.finish_holder(p) is None and not release.finish_lock(p).exists()
    with pytest.raises(SystemExit) as e:
        cli.main(["upgrade", "demo"])
    tid = p.db.one("SELECT id FROM tasks WHERE kind='harness'")["id"]
    out = capsys.readouterr().out
    assert e.value.code == 75 and f"Harness task #{tid} finishes it" in out and "now targets" not in out
    assert release.finish_holder(p)["task"] == tid and not restarts
    p.db.update_task(tid, status="failed")
    p.db.x("UPDATE tasks SET created=? WHERE id=?", (time.time() - 2 * release.TASK_EVERY_S, tid))
    _next_release(env)
    with pytest.raises(SystemExit) as e:
        cli.main(["upgrade", "demo"])
    tids = [t["id"] for t in p.db.q("SELECT id FROM tasks WHERE kind='harness' ORDER BY id")]
    assert e.value.code == 75 and len(tids) == 2 and release.finish_holder(p)["task"] == tids[1]
    assert "Retargeted" not in p.db.task(tids[1])["spec"]


def test_upgrade_stops_clearly_on_an_unfinished_merge_in_the_live_harness(env, monkeypatch, capsys):
    """A hand-run merge the guard hook refused left MERGE_HEAD and its files behind; the upgrade then
    tried to commit them as local changes and died with the hook's refusal instead of saying why."""
    p = make(env)
    from ttp import cli, service
    restarts = []
    monkeypatch.setattr(service, "restart", lambda p: restarts.append(1) or "restarted")
    h = p.harness
    ident = ["-c", "user.name=t", "-c", "user.email=t@t"]
    _git_out(h, "checkout", "-qb", "side")
    (h / "prompts" / "worker.md").write_text("side change\n")
    _git_out(h, *ident, "commit", "-qam", "side")
    _git_out(h, "checkout", "-q", "-")
    head = _git_out(h, "rev-parse", "HEAD")
    _git_out(h, *ident, "merge", "-q", "--no-commit", "--no-ff", "side")
    _install_template(env)
    capsys.readouterr()
    with pytest.raises(SystemExit) as e:
        cli.main(["upgrade", "demo"])
    err = capsys.readouterr().err
    assert e.value.code == 1 and "unfinished merge" in err and "prompts/worker.md" in err
    assert "merge --abort" in err and "unfinished merge" in (p.logs / "upgrade.log").read_text()
    assert _git_out(h, "rev-parse", "HEAD") == head and _git_out(h, "rev-parse", "-q", "--verify", "MERGE_HEAD")
    assert not restarts and not p.db.one("SELECT * FROM tasks WHERE kind='harness'")
    # The automatic upgrade records the reason, so the status line shows it.
    from ttp import release
    p.db.set_kv(release.KV_AUTO, {"outcome": "running"})
    with pytest.raises(SystemExit):
        cli.main(["upgrade", "demo", "--auto", "--project-dir", str(p.base)])
    rec = p.db.kv(release.KV_AUTO)
    assert rec["outcome"] == "failed" and "unfinished merge" in rec["why"]
    # Once the merge is aborted, the upgrade goes through.
    _git_out(h, "merge", "--abort")
    cli.main(["upgrade", "demo"])
    assert restarts == [1] and (h / "prompts" / "worker.md").read_text() != "side change\n"


def test_the_merge_guard_refuses_update_ref_onto_upstream_without_an_old_value(env, monkeypatch, tmp_path):
    from ttp import release
    monkeypatch.delenv(release.GUARD_ENV, raising=False)
    h = tmp_path / "harness"
    h.mkdir()
    ident = ["-c", "user.name=t", "-c", "user.email=t@t"]
    _git_out(h, "init", "-q", "-b", "main")
    (h / "a").write_text("a\n")
    _git_out(h, "add", "-A")
    _git_out(h, *ident, "commit", "-qm", "local")
    base = _git_out(h, "rev-parse", "HEAD")
    up = _git_out(h, *ident, "commit-tree", "-m", "template", _git_out(h, "rev-parse", "HEAD^{tree}"))
    _git_out(h, "update-ref", "refs/heads/upstream", up)
    merge = _git_out(h, *ident, "commit-tree", "-p", base, "-p", up, "-m", "merge upstream",
                     _git_out(h, "rev-parse", "HEAD^{tree}"))
    local = _git_out(h, *ident, "commit-tree", "-p", base, "-m", "local work", _git_out(h, "rev-parse", "HEAD^{tree}"))
    assert release.guard_harness(h)
    # Git passes the zero oid as the old value when none is given: the guard checks main's real value.
    for argv in (["update-ref", "refs/heads/main", merge], ["update-ref", "refs/heads/main", merge, base]):
        r = subprocess.run(["git", "-C", str(h), *argv], capture_output=True, text=True)
        assert r.returncode != 0 and "only `ttp upgrade`" in r.stderr
        assert _git_out(h, "rev-parse", "main") == base
    # A genuinely new ref, and main moving onto local work, still go through.
    _git_out(h, "update-ref", "refs/heads/fresh", merge)
    assert _git_out(h, "rev-parse", "fresh") == merge
    _git_out(h, "update-ref", "refs/heads/main", local)
    assert _git_out(h, "rev-parse", "main") == local


def test_restart_rolls_back_a_runtime_the_daemon_cannot_start_with(env):
    import py_compile
    p = make(env)
    from ttp import service
    h = p.harness
    p.db.set_kv("harness_good", {"commit": _git_out(h, "rev-parse", "HEAD")})

    def fake_restart(p):
        try:
            py_compile.compile(str(h / "runtime" / "ttp" / "daemon.py"), doraise=True)
        except py_compile.PyCompileError:
            return "restarted"      # the daemon dies on import: no heartbeat
        (p.state / "heartbeat").write_text(json.dumps({"pid": 1, "started": time.time()}))
        return "restarted"

    assert "daemon is running" in service.restart(p, wait_s=0.5, restart_fn=fake_restart)
    (h / "CHARTER.md").write_text((h / "CHARTER.md").read_text() + "\nA charter edit.\n")
    daemon_py = h / "runtime" / "ttp" / "daemon.py"
    daemon_py.write_text(daemon_py.read_text() + "\ndef broken(:\n")
    _git_out(h, "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qam", "tweak the daemon")
    text = service.restart(p, wait_s=0.5, restart_fn=fake_restart)
    assert "tweak the daemon" in text and "running again" in text
    py_compile.compile(str(daemon_py), doraise=True)
    assert "A charter edit." in (h / "CHARTER.md").read_text(), "the rollback reverted more than the runtime"
    assert "tweak the daemon" in _git_out(h, "log", "--format=%s"), "history was rewritten"
    assert p.db.one("SELECT id FROM messages WHERE kind='alert' AND text LIKE '%rolled back%'")


def _runtime_change(h):
    daemon_py = h / "runtime" / "ttp" / "daemon.py"
    daemon_py.write_text(daemon_py.read_text() + "\n# a runtime change\n")
    _git_out(h, "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qam", "change the runtime")
    return _git_out(h, "rev-parse", "HEAD")


def test_restart_leaves_a_live_daemon_in_a_slow_first_tick_alone(env):
    import threading
    p = make(env)
    from ttp import service
    h = p.harness
    p.db.set_kv("harness_good", {"commit": _git_out(h, "rev-parse", "HEAD")})
    head = _runtime_change(h)

    def started_alive(p, tick_after=None):
        (p.state / "daemon.start").write_text(json.dumps({"pid": os.getpid(), "started": time.time(),
                                                          "tick_errors": 0}))
        if tick_after is not None:
            beat = json.dumps({"pid": os.getpid(), "started": time.time()})
            threading.Timer(tick_after, lambda: (p.state / "heartbeat").write_text(beat)).start()
        return "restarted"

    # The first tick ends after wait_s is over, but within tick_wait_s.
    text = service.restart(p, wait_s=0.3, tick_wait_s=10, restart_fn=lambda p: started_alive(p, tick_after=0.8))
    assert "daemon is running" in text
    text = service.restart(p, wait_s=0.3, tick_wait_s=0.6, restart_fn=started_alive)
    assert "still in its first tick" in text
    assert _git_out(h, "rev-parse", "HEAD") == head, "a live daemon's runtime was rolled back"
    assert not p.db.one("SELECT id FROM messages WHERE kind='alert' AND text LIKE '%rolled back%'")


@pytest.mark.parametrize("failure", ["exited", "tick_errors"])
def test_restart_rolls_back_when_the_new_daemon_dies_or_its_first_tick_fails(env, failure):
    p = make(env)
    from ttp import service
    h = p.harness
    good = _git_out(h, "rev-parse", "HEAD")
    p.db.set_kv("harness_good", {"commit": good})
    _runtime_change(h)
    dead = subprocess.Popen(["true"])
    dead.wait()

    def fake_restart(p):
        if subprocess.run(["git", "-C", str(h), "diff", "--quiet", good, "HEAD", "--", "runtime"]).returncode == 0:
            (p.state / "heartbeat").write_text(json.dumps({"pid": os.getpid(), "started": time.time()}))
        elif failure == "exited":
            (p.state / "daemon.start").write_text(json.dumps({"pid": dead.pid, "started": time.time()}))
        else:
            (p.state / "daemon.start").write_text(json.dumps({"pid": os.getpid(), "started": time.time(),
                                                              "tick_errors": 2}))
        return "restarted"

    text = service.restart(p, wait_s=30, tick_wait_s=30, restart_fn=fake_restart)
    assert "rolled back" in text and "running again" in text
    assert subprocess.run(["git", "-C", str(h), "diff", "--quiet", good, "HEAD", "--", "runtime"]).returncode == 0


@pytest.mark.parametrize("platform", ["linux", "darwin"])
@pytest.mark.parametrize("exits_after", [45, None])
def test_a_cron_restart_waits_for_the_old_daemon_and_never_rolls_it_back(env, monkeypatch, exits_after, platform):
    # With no launchd agent or systemd unit (on macOS too: a daemon started by hand, or a failed
    # bootstrap), a restart stops the old daemon and starts a new one itself.
    p = make(env)
    from ttp import daemon as dm, service
    monkeypatch.setenv("HOME", str(env["tmp"] / "userhome"))
    monkeypatch.setattr(service.sys, "platform", platform)
    monkeypatch.setattr(service, "_run", lambda *a: subprocess.CompletedProcess(a, 1, "", "no such service"))
    h = p.harness
    p.db.set_kv("harness_good", {"commit": _git_out(h, "rev-parse", "HEAD")})
    head = _runtime_change(h)
    old = subprocess.Popen(["sleep", "600"])
    (p.state / "daemon.pid").write_text(str(old.pid))

    class Clock:
        now = time.time()

        def time(self):
            return self.now

        def sleep(self, s):
            self.now += s

    clock = Clock()
    t0 = clock.now
    old_alive = lambda pid: pid == old.pid and (exits_after is None or clock.now < t0 + exits_after)  # noqa: E731
    monkeypatch.setattr(service, "time", clock)
    monkeypatch.setattr(dm, "_alive", old_alive)
    monkeypatch.setattr(dm, "_is_daemon", old_alive)

    def spawn(p):
        if old_alive(old.pid):
            return   # the new daemon finds the lock held and exits at once
        (p.state / "daemon.pid").write_text(str(os.getpid()))
        (p.state / "daemon.start").write_text(json.dumps({"pid": os.getpid(), "started": clock.now}))
        (p.state / "heartbeat").write_text(json.dumps({"pid": os.getpid(), "started": clock.now}))

    monkeypatch.setattr(service, "_spawn", spawn)
    try:
        text = service.restart(p)
    finally:
        old.kill()
        old.wait()
    assert ("daemon is running" in text) if exits_after else ("old daemon has not exited" in text)
    assert _git_out(h, "rev-parse", "HEAD") == head, "the runtime was rolled back while the old daemon lived"
    assert not p.db.one("SELECT id FROM messages WHERE kind='alert' AND text LIKE '%rolled back%'")


BUS_DOWN = "Failed to connect to bus: No data available"


def _sandboxed_systemd(env, monkeypatch, stderr=BUS_DOWN, takes=True, age=1.0):
    """A systemd project seen from a sandboxed worker: `systemctl --user` fails with `stderr`, the
    daemon's pid is not visible, and its heartbeat file (age s old) is the only sign it runs."""
    p = make(env)
    from ttp import daemon as dm, service
    monkeypatch.setenv("HOME", str(env["tmp"] / "userhome"))
    monkeypatch.setattr(service.sys, "platform", "linux")
    service._unit(p).parent.mkdir(parents=True, exist_ok=True)
    service._unit(p).write_text(service._unit_text(p))
    calls = []

    def run(*a):
        calls.append(a)
        rc = 1 if a[:3] == ("systemctl", "--user", "restart") else 0
        return subprocess.CompletedProcess(a, rc, "", stderr if rc else "")

    monkeypatch.setattr(service, "_run", run)
    monkeypatch.setattr(dm, "_alive", lambda pid: False)       # another pid namespace
    (p.state / "daemon.pid").write_text("4242")
    hb = p.state / "heartbeat"
    hb.write_text(json.dumps({"pid": 4242, "started": time.time() - 3600,
                              **({"takes": ["restart_requests"]} if takes else {})}))
    os.utime(hb, (time.time() - age, time.time() - age))
    h = p.harness
    good = _git_out(h, "rev-parse", "HEAD")
    p.db.set_kv("harness_good", {"commit": good})
    return p, _runtime_change(h), calls


def _no_rollback(p, head):
    assert _git_out(p.harness, "rev-parse", "HEAD") == head, "a healthy daemon's runtime was rolled back"
    assert not p.db.one("SELECT id FROM messages WHERE kind='alert' AND text LIKE '%rolled back%'")


def test_a_sandboxed_restart_asks_the_running_daemon_and_reports_its_outcome(env, monkeypatch):
    import threading
    from ttp import service
    p, head, calls = _sandboxed_systemd(env, monkeypatch)
    spawned = []
    real_popen = subprocess.Popen
    monkeypatch.setattr(service.subprocess, "Popen", lambda argv, **kw: spawned.append((argv, kw))
                        if "ttp.service" in argv else real_popen(argv, **kw))

    def daemon_side():      # the daemon's next tick takes the request; its restart from the host reports back
        deadline = time.time() + 10
        while time.time() < deadline and not service.take_restart_request(p, started=time.time() - 3600):
            time.sleep(0.05)
        at = json.loads((p.state / "restart.request.taken").read_text())["at"]
        (p.state / "restart.result").write_text(json.dumps({"at": at, "outcome": "running",
                                                            "text": "restarted; the daemon is running"}))

    t = threading.Thread(target=daemon_side)
    t.start()
    res = service.restart(p, wait_s=5)
    t.join()
    assert res.outcome == "running" and "restarted itself on request" in res and BUS_DOWN in res, res
    _no_rollback(p, head)
    argv, kw = spawned[0]
    assert argv[1:3] == ["-m", "ttp.service"] and kw["start_new_session"]
    assert kw["env"]["PYTHONPATH"] == str(p.harness / "runtime"), "the restart must run the runtime on disk"
    # An older request (made before this daemon started) is done: dropped, not carried out again.
    (p.state / "restart.request").write_text(json.dumps({"at": time.time() - 60}))
    assert not service.take_restart_request(p, started=time.time()) and not (p.state / "restart.request").exists()
    assert len(spawned) == 1


def test_the_daemon_announces_and_takes_restart_requests_each_tick(env, monkeypatch):
    from ttp import daemon as dm, service, web
    p = make(env)
    d = dm.Daemon(p.base)
    taken = []

    def tick():
        if not taken:
            (p.state / "restart.request").write_text(json.dumps({"at": time.time(), "pid": 1}))
        d.stopping = len(taken) >= 1

    monkeypatch.setattr(d, "tick", tick)
    monkeypatch.setattr(service, "take_restart_request", lambda p, started: taken.append(started) or True)
    monkeypatch.setattr(web, "serve", lambda daemon: None)
    monkeypatch.setattr(dm.signal, "signal", lambda *a: None)
    monkeypatch.setattr(dm.time, "sleep", lambda s: None)
    assert d.run() == 0
    assert taken and set(taken) == {d._started}
    assert "restart_requests" in json.loads((p.state / "heartbeat").read_text())["takes"]


def test_the_requested_restart_runs_from_the_host_and_writes_its_result(env, monkeypatch):
    from ttp import service
    p = make(env)
    at = time.time()
    (p.state / "restart.request.taken").write_text(json.dumps({"at": at, "pid": 1}))
    seen = []

    def fake(p, requested=False):
        seen.append(requested)
        return service._said("rolled back to abc", "rolled_back")

    monkeypatch.setattr(service, "restart", fake)
    monkeypatch.setattr(service.sys, "argv", ["x", str(p.base)])
    assert service.main() == 1 and seen == [True], "the host-side restart must never ask the daemon again"
    res = json.loads((p.state / "restart.result").read_text())
    assert res["at"] == at and res["outcome"] == "rolled_back" and not (p.state / "restart.request.taken").exists()
    assert service._restart_result(p, at)["text"] == "rolled back to abc"


def _upgrade_probe(p) -> int:
    """The retry_when the upgrade task gives a worker whose restart was deferred, run as the harness runs it."""
    from ttp import cli
    line = next(x for x in cli._UPGRADE_TASK.splitlines() if "restart.request.taken" in x)
    probe = line.split("`")[1].format(state=shlex.quote(str(p.state)))
    return subprocess.run(probe, shell=True).returncode


def test_a_restart_helper_that_cannot_start_is_reaped_with_a_failed_result(env, monkeypatch):
    from ttp import service
    p = make(env)
    broken = env["tmp"] / "broken-runtime"
    (broken / "ttp").mkdir(parents=True)
    (broken / "ttp" / "__init__.py").write_text("raise ImportError('the new runtime is broken')\n")
    monkeypatch.setattr(service, "_env", lambda p: {"PYTHONPATH": str(broken)})
    started = time.time() - 3600
    at = time.time()
    (p.state / "restart.request").write_text(json.dumps({"at": at, "pid": 1, "why": "upgrade"}))
    assert service.take_restart_request(p, started)
    assert _upgrade_probe(p) != 0, "the probe must keep waiting while the restart runs"
    assert service.reap_restart_request(p, started) is None, "a running helper is left alone"
    assert service._helpers[str(p.base)].wait(timeout=60) != 0
    assert service.reap_restart_request(p, started) == "failed"
    res = service._restart_result(p, at)
    assert res["outcome"] == "failed" and "could not start" in res["text"] and "the new runtime is broken" in res["text"]
    assert not (p.state / "restart.request.taken").exists() and _upgrade_probe(p) == 0
    alerts = p.db.q("SELECT text FROM messages WHERE kind='alert' AND severity='high'")
    assert len(alerts) == 1 and "could not start" in alerts[0]["text"]
    assert service.reap_restart_request(p, started) is None and len(
        p.db.q("SELECT id FROM messages WHERE kind='alert'")) == 1, "reported once"


def test_a_restart_helper_interrupted_without_a_handle_is_reaped_after_its_bound(env, monkeypatch):
    from ttp import service
    p = make(env)
    started = time.time() - 7200
    at = time.time() - service.HELPER_BOUND_S - 60
    (p.state / "restart.request.taken").write_text(json.dumps({"at": at, "pid": 1, "taken": at}))
    (p.logs / "restart.log").parent.mkdir(parents=True, exist_ok=True)
    (p.logs / "restart.log").write_text(f"--- x restart requested by pid 1: upgrade\n{service.HELPER_STARTED} (pid 9)\n")
    assert service.reap_restart_request(p, started) == "failed"
    res = service._restart_result(p, at)
    assert "was interrupted" in res["text"] and service.HELPER_STARTED in res["text"]
    assert not (p.state / "restart.request.taken").exists()
    # Within the bound, with no handle (it cannot be told whether the helper still runs), it waits.
    (p.state / "restart.request.taken").write_text(json.dumps({"at": time.time(), "taken": time.time()}))
    assert service.reap_restart_request(p, started) is None and (p.state / "restart.request.taken").exists()


def test_a_restart_helper_hung_past_its_bound_is_killed_with_its_group_and_labelled_hung(env, monkeypatch):
    from ttp import service
    p = make(env)
    at = time.time() - service.HELPER_BOUND_S - 60
    (p.state / "restart.request.taken").write_text(json.dumps({"at": at, "pid": 1, "taken": at}))
    kid = env["tmp"] / "hung-child.pid"
    proc = subprocess.Popen(["sh", "-c", f"sleep 600 & echo $! > {shlex.quote(str(kid))}; wait"],
                            start_new_session=True)
    monkeypatch.setitem(service._helpers, str(p.base), proc)
    deadline = time.time() + 10
    while not (kid.exists() and kid.read_text().strip()) and time.time() < deadline:
        time.sleep(0.05)
    child = int(kid.read_text())
    try:
        assert service.reap_restart_request(p, time.time() - 7200) == "failed"
        assert proc.poll() is not None, "the hung helper must be stopped before it is reported"
        deadline = time.time() + 10
        while time.time() < deadline:
            try:
                os.kill(child, 0)
            except ProcessLookupError:
                break
            time.sleep(0.05)
        else:
            raise AssertionError("the helper's own children must go with its process group")
        res = service._restart_result(p, at)
        assert "hung" in res["text"] and "was stopped" in res["text"] and "was interrupted" not in res["text"]
        assert "nothing was restarted or rolled back" in res["text"]
        assert not (p.state / "restart.request.taken").exists() and str(p.base) not in service._helpers
    finally:
        for pid in (proc.pid, child):
            try:
                os.kill(pid, 9)
            except OSError:
                pass
        proc.wait(timeout=10)


def test_a_failing_restart_reap_never_stops_a_new_restart_request(env, monkeypatch):
    from ttp import daemon as dm, service, web
    p = make(env)
    d = dm.Daemon(p.base)
    taken = []

    def boom(p, started):
        raise RuntimeError("reap broke")

    monkeypatch.setattr(d, "tick", lambda: setattr(d, "stopping", True))
    monkeypatch.setattr(service, "reap_restart_request", boom)
    monkeypatch.setattr(service, "take_restart_request", lambda p, started: taken.append(started) or True)
    monkeypatch.setattr(web, "serve", lambda daemon: None)
    monkeypatch.setattr(dm.signal, "signal", lambda *a: None)
    monkeypatch.setattr(dm.time, "sleep", lambda s: None)
    assert d.run() == 0
    assert taken == [d._started], "the restart request is still taken"
    text = (p.logs / "daemon.log").read_text()
    assert "restart reap error" in text and "reap broke" in text and "tick error" not in text


def test_a_daemon_started_after_the_request_was_taken_clears_the_leftover_claim(env, monkeypatch):
    from ttp import daemon as dm, service, web
    p = make(env)
    at = time.time() - 120
    (p.state / "restart.request.taken").write_text(json.dumps({"at": at, "pid": 1, "taken": at + 1}))
    d = dm.Daemon(p.base)
    monkeypatch.setattr(d, "tick", lambda: setattr(d, "stopping", True))
    monkeypatch.setattr(web, "serve", lambda daemon: None)
    monkeypatch.setattr(dm.signal, "signal", lambda *a: None)
    monkeypatch.setattr(dm.time, "sleep", lambda s: None)
    assert d.run() == 0
    res = service._restart_result(p, at)
    assert res and res["outcome"] == "running" and res["reaped"], res
    assert not (p.state / "restart.request.taken").exists() and _upgrade_probe(p) == 0
    assert not p.db.one("SELECT id FROM messages WHERE kind='alert'"), "a restart that happened is no alert"
    # A result the helper wrote before it died is kept; only the claim goes.
    (p.state / "restart.request.taken").write_text(json.dumps({"at": at, "taken": at + 1}))
    (p.state / "restart.result").write_text(json.dumps({"at": at, "outcome": "rolled_back", "text": "rb"}))
    assert service.reap_restart_request(p, time.time()) is None
    assert service._restart_result(p, at)["outcome"] == "rolled_back"
    assert not (p.state / "restart.request.taken").exists()


