def test_ttp_push_queue_lists_the_entries_and_the_last_ten_batches(env, monkeypatch, capsys):
    from ttp import cli, pushq
    p, rid = _pq_rows(env)
    now = time.time()
    sha = "cd" * 20
    for i in range(12):
        _pq_batch_row(p, f"b{i:02d}", now, age=7200 - i * 60, outcome="nothing", ended=now - 7000 + i * 60,
                      finalized=now, after_push="skipped", after_finalized=now)
    _pq_batch_row(p, "b20", now, age=900, outcome="pushed", pushed_sha=sha, version="0.2.140", ended=now - 720,
                  finalized=now, check_runs=2, check_s=242.4, after_push="failed", after_finalized=now)
    _pq_row(p, rid, now, status="pushed", batch="b20", age=1000, sha=sha, version="0.2.140")
    _pq_row(p, rid, now, age=361, head="ef" * 20)
    _pq_batch_row(p, "b21", now, age=30, phase="push")
    _pq_row(p, rid, now, status="batched", batch="b21", age=100, head="12" * 20)
    out = pushq.queue_text(p, now).splitlines()
    assert out[0].startswith("push queue: 1 approved (oldest 6 min) · batch checking since 0 min (1 change) · "
                             f"last pushed {sha[:7]} as 0.2.140 12 min ago · deploy failed"), out[0]
    i = out.index("entries:")
    assert out[i + 1:i + 4] == [
        f"  #{rid} ttp/t1-feature 1212121 batched in b21, 1 min old: review feature",
        f"  #{rid} ttp/t1-feature efefefe approved, 6 min old: review feature",
        f"  #{rid} ttp/t1-feature abababa pushed in b20, 16 min old: review feature"]
    j = out.index("batches, newest first:")
    assert out[j + 1] == "  b21 running: checking since 0 min, 1 change"
    assert out[j + 2] == f"  b20 12 min ago: pushed {sha[:7]} as 0.2.140, checks 2 runs in 242 s, deploy failed"
    assert out[j + 3].startswith("  b11 ") and out[j + 3].endswith("ago: nothing to push, no deploy")
    assert len(out) - j - 2 == 10, "the last 10 batches, plus the live one"
    # the CLI flag prints the same, from the project's folder, and pushes nothing
    monkeypatch.chdir(p.root)
    monkeypatch.setattr(sys, "argv", ["ttp", "push", "--queue"])
    cli.main()
    printed = capsys.readouterr().out
    assert "entries:" in printed and "b20 12 min ago: pushed" in printed


def test_the_web_app_shows_the_push_queue_card_and_the_pushed_sha_of_a_review(env):
    from ttp.web import state_payload
    p, rid = _pq_rows(env)
    assert state_payload(p, p.db)["push_queue"]["line"] == "push queue: empty"
    now = time.time()
    sha = "cd" * 20
    _pq_batch_row(p, "b1", now, age=900, outcome="pushed", pushed_sha=sha, version="0.2.140", ended=now - 720,
                  finalized=now, check_runs=1, check_s=200.0, after_push="ok", after_finalized=now)
    _pq_row(p, rid, now, status="pushed", batch="b1", sha=sha, version="0.2.140")
    p.db.update_task(rid, status="done", result=json.dumps({"status": "done", "summary": "ok", "pushed": [
        {"branch": "ttp/t1-feature", "head": "ab" * 20, "sha": sha, "version": "0.2.140", "batch": "b1",
         "status": "pushed"}]}))
    other = p.db.add_task("another review", "r", kind="review", origin="coordinator")
    p.db.update_task(other, status="pushing")
    _pq_row(p, other, now, age=120, head="ef" * 20)
    st = json.loads(json.dumps(state_payload(p, p.db), default=str))
    q = st["push_queue"]
    assert q["on"] and q["line"].startswith("push queue: 1 approved (oldest 2 min) · last pushed")
    assert [(e["task"], e["head"], e["status"]) for e in q["entries"]] == [(other, "efefefe", "approved"),
                                                                          (rid, "abababa", "pushed")]
    assert [(b["id"], b["outcome"], b["pushed_sha"], b["version"], b["check_runs"], b["after_push"])
            for b in q["last"]] == [("b1", "pushed", sha, "0.2.140", 1, "ok")]
    tasks = {t["id"]: t for t in st["tasks"]}
    assert tasks[rid]["pushed"] == [{"branch": "ttp/t1-feature", "sha": sha, "version": "0.2.140", "status": "pushed"}]
    assert tasks[other]["status"] == "pushing" and tasks[other]["pushed"] is None
    app = (RUNTIME / "ttp" / "web" / "app.js").read_text()
    assert "pushQueueHtml(st.push_queue, " in app and "t.pushed" in app
    assert 'id="pqcard"' in (RUNTIME / "ttp" / "web" / "index.html").read_text()


def test_only_the_three_push_queue_alerts_reach_the_top_section_and_only_while_active(env):
    from ttp import alerts
    from ttp.daemon import Daemon
    from ttp.web import state_payload
    p, rid = _pq_rows(env)
    d = Daemon(p.base)
    now = time.time()
    for key in ("push_rejected", "after_push_failed", "push_queue_dying"):
        d.alert(key, f"{key} text", severity="high")
    # The rest is news for the coordinator or the feed, never the top section.
    p.db.x("INSERT INTO events(ts,source,kind,severity,text,status) VALUES(?,?,?,?,?,?)",
           (now, "daemon", "push_tip_failed", "high", "the tip fails", "queued"))
    p.db.post("out", "push batch b0 ended nothing", chat=None, kind="info", severity="normal")
    top = lambda: sorted(m["text"] for m in state_payload(p, p.db)["attention"])  # noqa: E731
    assert top() == ["after_push_failed text", "push_queue_dying text", "push_rejected text"]
    later = time.time() + 1
    _pq_batch_row(p, "b1", later, age=0, outcome="pushed", pushed_sha="cd" * 20, ended=later, finalized=later,
                  after_push="ok", after_finalized=later)
    assert top() == [], "a pushed and deployed batch clears all three"
    assert sorted(ep["key"] for ep in alerts.sweep(p.db, later + 1)) == [
        "after_push_failed", "push_queue_dying", "push_rejected"]
    feed = [m for m in state_payload(p, p.db)["feed"] if m["state"] == "cleared"]
    assert sorted(m["text"] for m in feed) == ["after_push_failed text", "push_queue_dying text", "push_rejected text"]


def test_a_conflicting_push_runs_the_review_again_with_the_conflict_and_what_landed(env, monkeypatch):
    s = _pq(env, monkeypatch)
    base, onto, tip = _git_out(s.repo, "rev-parse", f"{s.head}^"), "ef" * 20, "aa" * 20
    _pq_plan(s, outcome="landed", tip=tip, rows={"base": "landed", s.branch: "conflict"},
             detail={"files": ["feature.txt"], "onto": onto})
    _pq_hand_off(env, s, push=[{"branch": "base", "head": base}, {"branch": s.branch, "head": s.head}])
    mark = _pq_mark(s.p)
    _pq_batch(s)
    _pq_tend(s)
    t = s.p.db.task(s.review)
    assert t["status"] == "queued" and json.loads(t["result"])["woke"] == (
        f"push conflict: {s.branch} at {s.head} conflicts with origin/proj at {onto} in feature.txt; "
        f"already landed: base at {base[:7]} (landed as {tip[:7]})")
    assert not [e for e in _pq_events(s.p, mark) if e["status"] == "queued"]
    # The review settles it on a commit it did not review before: allowed, and the event lists it.
    fix = _git_out(s.repo, "commit-tree", f"{s.head}^{{tree}}", "-p", s.head, "-m", "settle the conflict")
    t = _pq_hand_off(env, s, push=[{"branch": s.branch, "head": fix}])
    assert t["status"] == "pushing"
    [q] = [e for e in _pq_events(s.p, mark) if e["kind"] == "push_queued"]
    assert "settle the conflict" in q["text"] and q["status"] == "handled"


def test_a_code_task_in_review_is_closed_when_a_review_that_settled_its_push_conflict_pushes_it(env, monkeypatch):
    """The code task waits in 'review'; its review's approval conflicts, and another review, named
    after the code task, settles the conflict and pushes: the code task is done with that push."""
    s = _pq(env, monkeypatch)
    s.p.db.update_task(s.code, status="review", result=json.dumps({"status": "needs_review", "summary": "built it"}))
    _pq_plan(s, outcome="nothing", rows={s.branch: "conflict"}, detail={"files": ["feature.txt"], "onto": "ef" * 20})
    _pq_hand_off(env, s)
    _pq_batch(s)
    _pq_tend(s)
    assert s.p.db.task(s.review)["status"] == "queued" and s.p.db.task(s.code)["status"] == "review"
    s.p.db.update_task(s.review, status="cancelled")
    fix = _git_out(s.repo, "commit-tree", f"{s.head}^{{tree}}", "-p", s.head, "-m", "settle the conflict")
    settle = s.p.db.add_task(f"Review #{s.code}: settle the push conflict", f"{s.branch} rebased as {fix}: push it",
                             kind="review", tier="standard", origin="coordinator")
    sha = "cd" * 20
    _pq_plan(s, outcome="pushed", sha=sha, version="0.3.1")
    own = [{"branch": f"ttp/t{settle}-settle", "head": fix}]   # pushed on a branch of its own
    assert _pq_hand_off(env, s, push=own, task=settle)["status"] == "pushing"
    mark = _pq_mark(s.p)
    _pq_batch(s)
    _pq_tend(s)
    assert s.p.db.task(settle)["status"] == "done"
    t = s.p.db.task(s.code)
    res = json.loads(t["result"])
    assert t["status"] == "done" and res["shipped_by"] == settle
    assert [(x["sha"], x["version"], x["status"]) for x in res["pushed"]] == [(sha, "0.3.1", "pushed")]
    assert res["summary"] == f"built it (shipped by review #{settle}: pushed {sha[:7]} as 0.3.1)"
    [ev] = [e for e in _pq_events(s.p, mark, task=s.code)]
    assert ev["kind"] == "task_done" and ev["status"] == "handled", "a shipped task is no news for the coordinator"


def test_the_daemon_closes_code_tasks_left_in_review_whose_latest_review_pushed_them(env):
    """Clean-up of tasks left behind: only a task whose latest covering review is done and pushed its
    work after the task entered review is closed, once."""
    from ttp import pushq
    from ttp.daemon import Daemon
    p, _ = _pq_rows(env)
    db, now = p.db, time.time()

    def code(name, at):
        tid = db.add_task(name, "s", kind="code", tier="light", origin="user")
        db.update_task(tid, status="review", branch=f"ttp/t{tid}-{name}")
        db.x("UPDATE tasks SET updated=? WHERE id=?", (at, tid))
        return tid

    def review(title, status, row=None, at=now, **kw):
        rid = db.add_task(title, "r", kind="review", origin="coordinator", **kw)
        db.update_task(rid, status=status)
        if row:
            db.x("INSERT INTO push_queue(task, branch, head, target, status, batch, created, updated, pushed_sha, "
                 "version) VALUES(?,?,?,?,?,?,?,?,?,?)", (rid, row, "ab" * 20, "origin/proj", "pushed", "b1",
                                                          at - 60, at, "cd" * 20, "0.3.2"))
        return rid

    shipped, by_branch, by_dep = code("shipped", now - 500), code("branch", now - 500), code("dep", now - 500)
    reopened, pending, unreviewed = code("reopened", now - 100), code("pending", now - 500), code("none", now - 500)
    review(f"Review #{shipped}: x", "failed")                          # an earlier round, failed on a conflict
    done = review(f"Review #{shipped}: settle the conflict", "done", f"ttp/t{shipped}-shipped")
    review("land it", "done", f"ttp/t{by_branch}-branch")             # pushed the task's branch
    review("review the stack", "done", "ttp/other", depends_on=[by_dep])
    review(f"Review #{reopened}: x", "done", f"ttp/t{reopened}-reopened", at=now - 300)   # before it re-entered review
    review(f"Review #{pending}: x", "done", f"ttp/t{pending}-pending")
    review(f"Review #{pending}: again", "queued")                                          # a newer review still open
    Daemon(p.base).tend_pushes()
    st = {i: db.task(i)["status"] for i in (shipped, by_branch, by_dep, reopened, pending, unreviewed)}
    assert st == {shipped: "done", by_branch: "done", by_dep: "done", reopened: "review", pending: "review",
                  unreviewed: "review"}
    res = json.loads(db.task(shipped)["result"])
    assert res["shipped_by"] == done and res["pushed"][0]["sha"] == "cd" * 20 and res["pushed"][0]["version"] == "0.3.2"
    assert len(db.q("SELECT id FROM events WHERE kind='task_done'")) == 3
    assert pushq.settle_reviewed(db) == [] and len(db.q("SELECT id FROM events WHERE kind='task_done'")) == 3


