def test_remote_upstream_inboxes_are_read_over_ssh_at_most_hourly(env, monkeypatch):
    p = make(env)
    from ttp import upstream
    from ttp.project import register
    register("far", {"host": "farbox", "dir": "/w/far"})
    p.set_config("upstream.ingest", True)
    line = json.dumps({"fp": "f1", "project": "far", "host": "farbox", "task": 9, "title": "upstream: remote",
                       "spec": "r"}) + "\n"
    calls = []

    def fake_run(argv, **kw):
        calls.append(argv)
        tail = int(argv[-1].split("tail -c +")[1].split()[0])
        body = line.encode()[tail - 1:]
        return subprocess.CompletedProcess(argv, 0, f"{len(line)}\n".encode() + body, b"")
    monkeypatch.setattr(upstream.subprocess, "run", fake_run)
    now = time.time()
    assert upstream.ingest(p, p.config(), now) == 1
    assert len(calls) == 1 and calls[0][-2] == "farbox" and "tail -c +1 " in calls[0][-1]
    assert upstream.ingest(p, p.config(), now + 1800) == 0 and len(calls) == 1, "read again within the hour"
    assert upstream.ingest(p, p.config(), now + 3700) == 0 and len(calls) == 2
    assert f"tail -c +{len(line) + 1} " in calls[1][-1], "the remote cursor did not move"
    assert "upstream-reader.json" in calls[0][-1], "the remote inbox was not marked read"


def test_remote_upstream_reads_use_sh_c_no_stdin_and_end_options(env, monkeypatch):
    from ttp import upstream
    seen = {}

    def fake_run(argv, **kw):
        seen.update(argv=argv, kw=kw)
        return subprocess.CompletedProcess(argv, 0, b"0\n", b"")
    monkeypatch.setattr(upstream.subprocess, "run", fake_run)
    assert upstream._read_remote("-oProxyCommand=x", 5, {"project": "it's", "host": "h", "ts": 1}) == (b"", 0)
    argv = seen["argv"]
    assert argv[:-3] == upstream.SSH and argv[-3:-1] == ["--", "-oProxyCommand=x"]
    assert seen["kw"]["stdin"] is subprocess.DEVNULL and seen["kw"]["timeout"] == upstream.REMOTE_TIMEOUT_S
    words = shlex.split(argv[-1])
    assert words[:2] == ["sh", "-c"] and len(words) == 3, "the remote command is not one sh -c argument"
    assert "tail -c +6 " in words[2]
    # The command runs as written under a POSIX shell (here, with a home of its own).
    monkeypatch.undo()
    home = env["tmp"] / "remote-home"
    (home / ".tt-project").mkdir(parents=True)
    (home / ".tt-project" / "upstream.jsonl").write_bytes(b"0123456789\n")
    r = subprocess.run(["sh", "-c", argv[-1]], capture_output=True, env={"HOME": str(home), "PATH": os.environ["PATH"]})
    assert r.returncode == 0 and r.stdout == b"11\n56789\n"
    assert json.loads((home / ".tt-project" / "upstream-reader.json").read_text())["project"] == "it's"
    # BSD wc (macOS) pads the count: the command strips it, and the parser copes with padding too.
    assert "wc -c < \"$f\" | tr -d ' '" in words[2]
    monkeypatch.setattr(upstream.subprocess, "run",
                        lambda argv, **kw: subprocess.CompletedProcess(argv, 0, b"      11\n56789\n", b""))
    assert upstream._read_remote("h", 5, {"project": "p"}) == (b"56789\n", 11)


def test_remote_upstream_reads_stop_at_the_tick_budget_and_resume_fairly(env, monkeypatch):
    p = make(env)
    from ttp import upstream
    from ttp.project import register
    for h in ("hostA", "hostB", "hostC", "hostD"):
        register(f"far-{h}", {"host": h, "dir": f"/w/{h}"})
    p.set_config("upstream.ingest", True)
    clock, calls = [1000.0], []

    def fake_run(argv, **kw):
        calls.append(argv[-2])
        clock[0] += kw["timeout"]          # every machine hangs until its timeout
        raise subprocess.TimeoutExpired(argv, kw["timeout"])
    monkeypatch.setattr(upstream.subprocess, "run", fake_run)
    monkeypatch.setattr(upstream, "_clock", lambda: clock[0])
    now = time.time()
    t0 = clock[0]
    upstream.ingest(p, p.config(), now)
    assert calls == ["hostA", "hostB"] and clock[0] - t0 <= upstream.REMOTE_BUDGET_S
    # The next tick reads the machines left over first, then the round is done for the hour.
    upstream.ingest(p, p.config(), now + 60)
    assert calls == ["hostA", "hostB", "hostC", "hostD"]
    upstream.ingest(p, p.config(), now + 120)
    assert len(calls) == 4, "a finished round started again within the hour"
    upstream.ingest(p, p.config(), now + 3700)
    assert calls[4:] == ["hostA", "hostB"]
    # A machine whose project is gone is dropped from the round without a read.
    from ttp.project import unregister
    unregister("far-hostC")
    upstream.ingest(p, p.config(), now + 3760)
    assert calls[6:] == ["hostD"]



def _fake_forward_ssh(env, monkeypatch) -> dict:
    """An `ssh` on PATH that runs the remote command locally, in a home of its own per target
    (tmp/remote/<target>), with that target as its host name; never a real host. `mode` file: `down`
    (exit 255), `hang` (sleeps), `drop-ack` (the target files the notes, the ack is lost)."""
    bin_dir, remote = env["tmp"] / "fake-bin", env["tmp"] / "remote"
    bin_dir.mkdir(exist_ok=True)
    remote.mkdir(exist_ok=True)
    fake = {"bin": bin_dir, "remote": remote, "log": env["tmp"] / "ssh.log", "mode": env["tmp"] / "ssh.mode"}
    (bin_dir / "ttp").write_text(f"#!/bin/sh\nexec {shlex.quote(sys.executable)} "
                                 f"{shlex.quote(str(RUNTIME.parent / 'bin' / 'ttp'))} \"$@\"\n")
    (bin_dir / "ssh").write_text(f"""#!/bin/sh
for last; do :; done
while [ "$1" != "--" ]; do shift; done
target=$2
echo "$target" >> {shlex.quote(str(fake['log']))}
mode=$(cat {shlex.quote(str(fake['mode']))} 2>/dev/null)
[ "$mode" = down ] && {{ echo "ssh: connect to host $target: Network is unreachable" >&2; exit 255; }}
[ "$mode" = hang ] && {{ sleep 300; exit 0; }}
mkdir -p {shlex.quote(str(remote))}/$target/.tt-project
HOME={shlex.quote(str(remote))}/$target TTP_HOME={shlex.quote(str(remote))}/$target/.tt-project TTP_HOST=$target \\
  PATH={shlex.quote(str(bin_dir))}:$PATH sh -c "$last"
rc=$?
[ "$mode" = drop-ack ] && exit 255
exit $rc
""")
    for x in ("ttp", "ssh"):
        (bin_dir / x).chmod(0o755)
    monkeypatch.setenv("PATH", f"{bin_dir}:{os.environ['PATH']}")
    return fake


def _remote_inbox(fake, target):
    f = fake["remote"] / target / ".tt-project" / "upstream.jsonl"
    return [json.loads(x) for x in f.read_text().splitlines()] if f.exists() else []


def _ssh_calls(fake):
    return fake["log"].read_text().split() if fake["log"].exists() else []


def test_upstream_notes_written_offline_reach_the_reading_machine_once(env, monkeypatch):
    """A machine the reader cannot reach sends its own notes on over ssh: after being offline, after a
    lost ack (the target dedupes), each to where it belongs, and nothing received is sent on again."""
    from ttp import upstream
    from ttp.project import register
    fake = _fake_forward_ssh(env, monkeypatch)
    register("example-project", {"host": "example-host", "dir": "/w/example"})
    register("other-project", {"host": "other-host", "dir": "/w/other"})
    reader_home = fake["remote"] / "example-host" / ".tt-project"
    reader_home.mkdir(parents=True)
    (reader_home / "upstream-reader.json").write_text(json.dumps(
        {"project": "reader-project", "host": "example-host", "ts": time.time()}))
    upstream.append("demo", 3, [{"title": "upstream: status hides waits", "spec": "show them"}])
    assert upstream.send("demo", 3, "example-project", "for you") == "sent"
    assert upstream.send("demo", 3, "other-project", "for the other") == "sent"
    # Offline: nothing moves, the failure is recorded, and the target waits out its back-off.
    fake["mode"].write_text("down")
    now = time.time()
    assert upstream.forward(now) == 0
    st = json.loads(upstream.forward_path().read_text())["targets"]
    assert st["example-host"]["fails"] == 1 and not st["example-host"].get("cursor")
    assert "Network is unreachable" in st["example-host"]["last_error"]
    assert any("failing" in x and "unreachable" in x for x in upstream.forward_status(now))
    calls = len(_ssh_calls(fake))
    assert upstream.forward(now + 30) == 0 and len(_ssh_calls(fake)) == calls, "tried again within its back-off"
    # Back online: a reading machine gets the general note and the one addressed to its project;
    # the machine without a reader gets only the note for its own project.
    fake["mode"].write_text("ok")
    assert upstream.forward(now + 3600) == 3
    got = _remote_inbox(fake, "example-host")
    assert sorted(n["title"] for n in got) == ["note to example-project", "upstream: status hides waits"]
    assert all(n["via"] == "testhost" and n["host"] == "testhost" and n["project"] == "demo" for n in got)
    assert [n["to"] for n in _remote_inbox(fake, "other-host")] == ["other-project"]
    # The cursor is on disk: a restarted daemon sends nothing again and contacts no one.
    size = upstream.path().stat().st_size
    assert all(t["cursor"] == size for t in json.loads(upstream.forward_path().read_text())["targets"].values())
    calls = len(_ssh_calls(fake))
    for mod in [m for m in list(sys.modules) if m == "ttp" or m.startswith("ttp.")]:
        del sys.modules[mod]
    from ttp import upstream
    assert upstream.forward(now + 3700) == 0 and len(_ssh_calls(fake)) == calls
    assert "read there by reader-project" in "\n".join(upstream.forward_status(now + 3700))
    # A lost ack: the target filed the note, the cursor stays, the resend is counted a duplicate.
    upstream.append("demo", 4, [{"title": "upstream: second", "spec": "s"}])
    fake["mode"].write_text("drop-ack")
    assert upstream.forward(now + 3800) == 0
    fake["mode"].write_text("ok")
    assert upstream.forward(now + 3800 + 3600) == 1
    assert [n["title"] for n in _remote_inbox(fake, "example-host")].count("upstream: second") == 1
    assert json.loads(upstream.forward_path().read_text())["targets"]["example-host"]["cursor"] == \
        upstream.path().stat().st_size
    # A note this machine received from another is never sent on again.
    line = {"ts": 1, "project": "far-project", "host": "far-host", "task": None, "title": "upstream: from afar",
            "spec": "x", "fp": upstream.fingerprint("upstream: from afar", "x")}
    ack, rc = upstream.receive((json.dumps(line) + "\n").encode(), "far-host")
    assert (rc, ack["accepted"]) == (0, 1)
    calls = len(_ssh_calls(fake))
    assert upstream.forward(now + 9000) == 0 and len(_ssh_calls(fake)) == calls
    # The coordinators here know the notes are read on the other machine.
    p = make(env)
    assert "sent on to example-host, where project reader-project reads" in upstream.digest_line(p, p.config())


def test_upstream_receive_rejects_malformed_and_oversize_notes(env, monkeypatch, capsys):
    from ttp import cli, upstream

    def line(title="upstream: ok", spec="s", **kw):
        n = {"ts": 1.0, "project": "example-project", "host": "example-host", "task": 5, "title": title,
             "spec": spec, "fp": upstream.fingerprint(title, spec), **kw}
        return (json.dumps(n) + "\n").encode()
    good = line()
    # A stream cut short, or with a line that is not JSON, files nothing at all.
    for bad in (good + good[:-1], good + b"{not json\n"):
        ack, rc = upstream.receive(bad, "example-host")
        assert rc != 0 and "error" in ack
    assert not upstream.path().exists()
    assert upstream.receive(good, "not an alias!")[1] != 0
    # Lines that are not notes, over the caps or with a fingerprint their text does not give are
    # rejected one by one; the rest are filed once, stamped with the sender.
    long_spec = "x" * (upstream.SPEC_CHARS + 1)
    forged = json.loads(line("upstream: other"))
    forged["fp"] = upstream.fingerprint("upstream: ok", "s")
    ack, rc = upstream.receive(good + line("not an upstream note") + line(spec=long_spec) + line(project="a b")
                               + (json.dumps(forged) + "\n").encode() + b"[1]\n" + good, "example-host")
    assert rc == 0 and (ack["accepted"], ack["duplicates"], ack["rejected"]) == (1, 1, 5)
    assert ack["last_fp"] == upstream.fingerprint("upstream: ok", "s")
    assert [(n["title"], n["via"]) for n in _upstream_inbox(env)] == [("upstream: ok", "example-host")]
    # Addressed notes keep their fields; unknown ones are dropped.
    text = "hello there"
    to = (json.dumps({"ts": 2, "project": "example-project", "host": "example-host", "task": None, "to": "demo",
                      "from": "worker", "severity": "high", "title": "note to demo", "spec": text, "run": "x",
                      "fp": upstream.fingerprint("to:demo", text)}) + "\n").encode()
    # Through the command: one JSON ack line on stdout.
    monkeypatch.setattr(sys, "stdin", type("S", (), {"buffer": io.BytesIO(to)})())
    with pytest.raises(SystemExit) as e:
        cli.main(["upstream", "--receive", "--via", "example-host"])
    assert e.value.code == 0
    assert json.loads(capsys.readouterr().out)["accepted"] == 1
    got = _upstream_inbox(env)[-1]
    assert (got["to"], got["severity"], got["via"], "run" in got) == ("demo", "high", "example-host", False)


def test_a_hung_ssh_never_holds_up_the_daemon_tick(env, monkeypatch):
    from ttp import upstream
    from ttp.daemon import Daemon
    from ttp.project import register
    fake = _fake_forward_ssh(env, monkeypatch)
    p = make(env)
    register("example-project", {"host": "example-host", "dir": "/w/example"})
    upstream.send("demo", 3, "example-project", "for you")
    fake["mode"].write_text("hang")
    monkeypatch.setattr(upstream, "FORWARD_EVERY_S", 0)
    monkeypatch.setattr(upstream, "FORWARD_TIMEOUT_S", 1)
    # No wall-clock limits, so a loaded machine cannot fail it: the ssh is held until the tick has
    # returned (off the tick's thread only; on it, it runs at once and the asserts below fail).
    real, go, ran_on = upstream.ssh_pipe, threading.Event(), []

    def held(*a):
        ran_on.append((threading.current_thread(), a[0]))
        if threading.current_thread() is not threading.main_thread():
            go.wait(60)
        return real(*a)
    monkeypatch.setattr(upstream, "ssh_pipe", held)
    d = Daemon(p.base)
    d.forward_upstream()
    first = d._forwarder
    assert first and first.is_alive(), "the tick waited on ssh"
    d.forward_upstream()                 # a pass still running is not started twice
    assert d._forwarder is first
    go.set()
    first.join(60)                       # the fake ssh hangs 300 s: only its 1 s timeout ends the pass
    assert not first.is_alive(), "the hung ssh was not cut off"
    assert ran_on == [(first, "example-host")], "ssh ran on the tick's thread, or more than once"
    st = json.loads(upstream.forward_path().read_text())["targets"]["example-host"]
    assert "no answer within 1 s" in st["last_error"] and not st.get("cursor")



def test_upstream_forwarding_stops_at_its_budget_and_starts_with_the_targets_left_over(env, monkeypatch):
    from ttp import upstream
    from ttp.project import register
    for h in ("host-a", "host-b", "host-c", "host-d"):
        register(f"project-{h}", {"host": h, "dir": f"/w/{h}"})
    clock, calls = [1000.0], []

    def hang(target, lines, timeout):
        calls.append(target)
        clock[0] += timeout                  # every machine hangs until its timeout
        return None, f"no answer within {timeout:.0f} s"
    monkeypatch.setattr(upstream, "_ssh_receive", hang)
    monkeypatch.setattr(upstream, "_clock", lambda: clock[0])
    now = time.time()
    upstream.forward(now)
    assert calls == ["host-a", "host-b"] and clock[0] - 1000 <= upstream.FORWARD_BUDGET_S
    upstream.forward(now + 1)                # all four still to try: the ones not yet tried go first
    assert calls[2:] == ["host-c", "host-d"]
    upstream.forward(now + 2)
    assert len(calls) == 4, "a failed target was tried again within its back-off"


def test_upstream_forward_batches_stay_under_the_receive_limit_and_skip_a_note_over_it(env, monkeypatch):
    from ttp import upstream
    from ttp.project import register
    register("example-project", {"host": "example-host", "dir": "/w/example"})
    sends = []

    def receive(target, lines, timeout):
        assert sum(map(len, lines)) <= upstream.RECEIVE_BYTES, "a send the receiver would refuse"
        sends.append(len(lines))
        return {"accepted": len(lines), "rejected": 0}, ""
    monkeypatch.setattr(upstream, "_ssh_receive", receive)
    monkeypatch.setattr(upstream, "RECEIVE_BYTES", 2000)
    upstream.send("demo", 3, "example-project", "x" * 5000)     # over the limit by itself
    for i in range(6):
        upstream.send("demo", 3, "example-project", f"note {i} " + "y" * 300)
    now = time.time()
    total = sum(upstream.forward(now + i) for i in range(10))
    sends = [n for n in sends if n]                              # not the empty probe
    assert total == 6 and len(sends) >= 2, sends
    st = json.loads(upstream.forward_path().read_text())["targets"]["example-host"]
    assert st["skipped"] == 1 and "skipped a note of" in st["last_error"]
    assert "1 skipped (too big to send)" in "\n".join(upstream.forward_status(now + 20))


def test_upstream_forward_counts_a_skipped_note_once_when_the_send_after_it_fails(env, monkeypatch):
    from ttp import upstream
    from ttp.project import register
    register("example-project", {"host": "example-host", "dir": "/w/example"})
    ok = [False]

    def receive(target, lines, timeout):
        if lines and not ok[0]:
            return None, "unreachable"
        return {"accepted": len(lines), "rejected": 0}, ""
    monkeypatch.setattr(upstream, "_ssh_receive", receive)
    monkeypatch.setattr(upstream, "RECEIVE_BYTES", 2000)
    upstream.send("demo", 3, "example-project", "x" * 5000)
    upstream.send("demo", 3, "example-project", "small note")
    now = time.time()
    for i in range(3):                                           # each send fails; back-off is skipped over
        upstream.forward(now + i * 10000)
    ok[0] = True
    assert upstream.forward(now + 40000) == 1
    st = json.loads(upstream.forward_path().read_text())["targets"]["example-host"]
    assert st["skipped"] == 1, st


def test_coordinators_pass_upstream_notes_on_only_while_no_project_reads_them(env):
    p = make(env)
    from ttp import upstream, coordinator as coord
    _, _, ids = _hand_off(env, p, {"status": "done", "summary": "ok",
                                   "followups": [{"title": "upstream: a lesson", "spec": "s"}]})
    assert "no project reads the user's upstream inbox. Pass" in coord.digest(p, {}, ids, [])
    upstream.reader_path().write_text(json.dumps({"project": "dev", "host": "box", "ts": time.time()}))
    dig = coord.digest(p, {}, ids, [])
    assert "project dev on box reads the user's upstream inbox" in dig and "Do not pass them on" in dig
    upstream.reader_path().write_text(json.dumps({"project": "dev", "host": "box", "ts": time.time() - 3 * 86400}))
    assert "no project reads" in coord.digest(p, {}, ids, []), "a reader long gone still silences the notes"
    # A turn without an upstream note carries no such line.
    _, _, plain = _hand_off(env, p, {"status": "done", "summary": "ok", "followups": [{"title": "x", "spec": "y"}]})
    assert "Upstream notes" not in coord.digest(p, {}, plain, [])


def _second_project(env, name="other"):
    """Another project of the same user on this machine, in its own repository."""
    from ttp.cli import bootstrap
    from ttp.project import register
    repo = env["tmp"] / f"repo-{name}"
    repo.mkdir()
    subprocess.run(["git", "init", "-q", str(repo)], check=True)
    (repo / "README.md").write_text("hi\n")
    subprocess.run(["git", "-C", str(repo), "add", "."], check=True)
    subprocess.run(["git", "-C", str(repo), "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "i"],
                   check=True)
    p = bootstrap(repo, name, "Keep it short.", "fake")
    register(name, {"host": "testhost", "dir": str(p.root)})
    return p


def test_two_projects_take_turns_on_a_shared_resource(env, tmp_path):
    a = make(env)
    b = _second_project(env)
    from ttp import coordinator as coord
    from ttp import machines as mm
    from ttp.cli import status_text
    from ttp.daemon import Daemon
    mm.add("board", tags="device", shared="")      # the user's machines list declares it shared
    env_a = dict(os.environ, TTP_HOME=str(env["home"]), TTP_HOST="testhost", TTP_PROJECT=str(a.base), TTP_TASK="3")
    env_b = dict(os.environ, TTP_HOME=str(env["home"]), TTP_HOST="testhost", TTP_PROJECT=str(b.base))
    release = tmp_path / "release"
    holder = subprocess.Popen([sys.executable, str(TTP), "lock", "board", "--", *_until(release)], env=env_a)
    slot = env["home"] / "locks" / "board" / "board.0.lock"
    try:
        deadline = time.time() + 20
        while time.time() < deadline and not (slot.exists() and slot.read_text()):
            time.sleep(0.05)
        assert not (a.state / "locks" / "board.0.lock").exists(), "a shared slot was kept per project"
        out = subprocess.run([sys.executable, str(TTP), "lock", "--timeout", "1", "board", "--", "true"],
                             env=env_b, capture_output=True, text=True)
        assert out.returncode == 75, "the other project got the board while this one held it"
        assert coord.apply(b, [{"type": "task_add", "title": "reflash", "spec": "s", "tier": "light",
                                "resources": ["board"], "exclusive": True}]) == []
        task = b.db.one("SELECT * FROM tasks WHERE title='reflash'")
        assert not Daemon(b.base)._resources_free(task), "an exclusive task started on a board another project holds"
        assert "shared board: demo task #3" in status_text(b), status_text(b)
    finally:
        release.touch()
        holder.wait(timeout=30)
    assert Daemon(b.base)._resources_free(task)
    assert subprocess.run([sys.executable, str(TTP), "lock", "--timeout", "5", "board", "--", "true"],
                          env=env_b).returncode == 0
    assert "shared board: free" in status_text(a)


def test_a_pause_of_a_shared_resource_holds_in_every_project(env, tmp_path):
    a = make(env)
    b = _second_project(env)
    from ttp import coordinator as coord
    from ttp.cli import status_text
    from ttp.daemon import Daemon
    for p in (a, b):
        p.set_config("shared_resources", ["board"])
    # A worker of b is using the board, and a task of a will wait on the pause.
    tb = b.db.add_task("soak", "s", kind="work", tier="light", origin="user", labels=["resource:board"])
    run_dir = tmp_path / "brun"
    run_dir.mkdir()
    b.db.x("INSERT INTO runs(task,role,provider,started,status,dir) VALUES(?,'worker','fake',?,'running',?)",
           (tb, time.time(), str(run_dir)))
    out = coord.pause_resource(a, "board", True, reason="maintenance", by="user")
    assert "for every project that shares it" in out, out
    got = b.db.paused_resources()["board"]
    assert got["project"] == "demo" and got["by"] == "user" and got["reason"] == "maintenance"
    assert "board" not in a.db.paused_resources(shared=False), "a shared pause was kept per project"
    env_b = dict(os.environ, TTP_HOME=str(env["home"]), TTP_HOST="testhost", TTP_PROJECT=str(b.base))
    out = subprocess.run([sys.executable, str(TTP), "lock", "--timeout", "5", "board", "--", "true"],
                         env=env_b, capture_output=True, text=True)
    assert out.returncode == 75 and "board is paused (maintenance)" in out.stderr, out
    assert coord.apply(b, [{"type": "task_add", "title": "flash", "spec": "s", "tier": "light",
                            "resources": ["board"]}]) == []
    assert not Daemon(b.base)._resources_free(b.db.one("SELECT * FROM tasks WHERE title='flash'"))
    assert "paused" in status_text(b) and "by user in demo" in status_text(b), status_text(b)
    # b's daemon tells its own worker once.
    coord.sync_shared_pauses(b)
    coord.sync_shared_pauses(b)
    assert (run_dir / "steer.md").read_text().count("`board` is paused (maintenance)") == 1
    # The coordinator of b may not lift a pause the user set.
    problems = coord.apply(b, [{"type": "resource_pause", "resource": "board", "paused": False}])
    assert any("paused by the user" in x for x in problems) and "board" in a.db.paused_resources(), problems
    # A task of a waits on the pause; b resumes the board, and a's daemon wakes it.
    ta = a.db.add_task("waits", "s", kind="work", tier="light", origin="user", labels=["resource:board"])
    a.db.update_task(ta, status="queued", not_before=time.time() + 7200, blocked_reason="waiting for board",
                     result=json.dumps({"status": "waiting", "waiting_for": "board (paused)",
                                        "retry_after_s": 7200, "waiting_since": time.time()}))
    assert coord.pause_resource(b, "board", False).startswith("board resumed for every project")
    assert "board" not in a.db.paused_resources()
    assert ta not in {t["id"] for t in a.db.ready_tasks()}
    coord.sync_shared_pauses(a)
    assert ta in {t["id"] for t in a.db.ready_tasks()}, "a resume from another project did not wake the task"
    assert "no longer paused" in (run_dir / "steer.md").read_text()


@pytest.mark.parametrize("how", ["unshare", "remove", "config", "list-merge"])
def test_a_user_pause_outlives_the_resource_leaving_the_share(env, tmp_path, capsys, how):
    a = make(env)
    b = _second_project(env)
    from ttp import cli
    from ttp import coordinator as coord
    from ttp import machines as mm
    if how == "config":
        for p in (a, b):
            p.set_config("shared_resources", ["board"])
    else:
        mm.add("board", tags="device", shared="")
    run_dir = tmp_path / "brun"
    run_dir.mkdir()
    tb = b.db.add_task("soak", "s", kind="work", tier="light", origin="user", labels=["resource:board"])
    b.db.x("INSERT INTO runs(task,role,provider,started,status,dir) VALUES(?,'worker','fake',?,'running',?)",
           (tb, time.time(), str(run_dir)))
    ta = a.db.add_task("waits", "s", kind="work", tier="light", origin="user", labels=["resource:board"])
    a.db.update_task(ta, status="queued", not_before=time.time() + 7200, blocked_reason="waiting for board",
                     result=json.dumps({"status": "waiting", "waiting_for": "board (paused)",
                                        "retry_after_s": 7200, "waiting_since": time.time()}))
    coord.pause_resource(a, "board", True, reason="flaky tray", by="user")
    for p in (a, b):   # each daemon ticks once while it is shared
        coord.sync_shared_pauses(p)
    if how == "unshare":
        with pytest.raises(SystemExit):
            cli.main(["machines", "add", "board", "--unshared"])
        assert "board is paused for every project" in capsys.readouterr().err
        with pytest.raises(ValueError):
            mm.add("board", shared="other")   # a new list without it unshares it too
    elif how == "remove":
        with pytest.raises(SystemExit):
            cli.main(["machines", "remove", "board"])
        assert "resume it first" in capsys.readouterr().err
        assert "board" in mm.load()
    elif how == "config":
        for p in (a, b):
            p.set_config("shared_resources", [])
    else:   # a copy of the list from another machine dropped it, past the refusal
        mm._save({"board": {"tags": ["device"], "note": "", "added": 1, "updated": 2}}, {})
    for _ in range(2):
        for p in (a, b):
            got = p.db.paused_resources().get("board")
            assert got and got["by"] == "user" and got["reason"] == "flaky tray", (how, p.name, got)
        for p in (a, b):
            coord.sync_shared_pauses(p)
    if how in ("config", "list-merge"):
        for p in (a, b):   # kept as each project's own pause
            assert p.db.paused_resources(shared=False)["board"]["by"] == "user"
        problems = coord.apply(b, [{"type": "resource_pause", "resource": "board", "paused": False}])
        assert any("paused by the user" in x for x in problems), problems
    assert ta not in {t["id"] for t in a.db.ready_tasks()}, "leaving the share woke a task waiting on the pause"
    assert "no longer paused" not in (run_dir / "steer.md").read_text()


def test_projects_that_give_a_shared_resource_different_slot_counts_use_the_smallest(env, tmp_path):
    a = make(env)
    b = _second_project(env)
    from ttp import coordinator as coord
    from ttp.cli import status_text
    from ttp.daemon import Daemon
    for p, n in ((a, 2), (b, 1)):
        p.set_config("shared_resources", ["board"])
        p.set_config("resources", {"board": n})
    coord.sync_shared_pauses(b)   # b's daemon records its count
    assert len(Daemon(a.base)._slot_paths("board")) == 1
    env_a = dict(os.environ, TTP_HOME=str(env["home"]), TTP_HOST="testhost", TTP_PROJECT=str(a.base))
    env_b = dict(env_a, TTP_PROJECT=str(b.base))
    release = tmp_path / "release"
    holder = subprocess.Popen([sys.executable, str(TTP), "lock", "board", "--", *_until(release)], env=env_a)
    slot = env["home"] / "locks" / "board" / "board.0.lock"
    try:
        deadline = time.time() + 20
        while time.time() < deadline and not (slot.exists() and slot.read_text()):
            time.sleep(0.05)
        # Both projects try at once: neither may take a second slot.
        tries = [subprocess.Popen([sys.executable, str(TTP), "lock", "--timeout", "1", "board", "--", "true"],
                                  env=e, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL) for e in (env_a, env_b)]
        for out in tries:
            assert out.wait(timeout=60) == 75, "a second slot was taken on a board one project allows once"
        assert not (env["home"] / "locks" / "board" / "board.1.lock").exists()
        assert "projects give different slot counts (demo 2, other 1); all use 1" in status_text(a), status_text(a)
        assert "Shared resource board: projects give different slot counts" in coord.digest(b, {}, [], [])
    finally:
        release.touch()
        holder.wait(timeout=30)
    # Once b stops sharing it, its count no longer holds a back.
    b.set_config("shared_resources", [])
    coord.sync_shared_pauses(b)
    assert len(Daemon(a.base)._slot_paths("board")) == 2
    assert "different slot counts" not in status_text(a)


