        d = Daemon(p.base)
        rid = d.start_run("coordinator", "go", "claude", "light", str(p.base), read_only=True,
                          unblock="user message")
        (p.runs / str(rid) / "STOP").touch()
        argv = json.loads((p.runs / str(rid) / "run.json").read_text())["argv"]
